update recipes set title = $j${"ru":"\u0410\u0434\u0430\u043d\u0430-\u043a\u0435\u0431\u0430\u0431 \u2014 \u043e\u0441\u0442\u0440\u044b\u0439 \u0442\u0443\u0440\u0435\u0446\u043a\u0438\u0439 \u043a\u0435\u0431\u0430\u0431 \u0438\u0437 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u044b","en":"Adana Kebab \u2014 Turkish Spiced Lamb Kebab","ua":"\u0410\u0434\u0430\u043d\u0430-\u043a\u0435\u0431\u0430\u0431 \u2014 \u0433\u043e\u0441\u0442\u0440\u0438\u0439 \u0442\u0443\u0440\u0435\u0446\u044c\u043a\u0438\u0439 \u043a\u0435\u0431\u0430\u0431 \u0437 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0438"}$j$::jsonb, description = $j${"ru":"\u0417\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u044b\u0439 \u043a\u0435\u0431\u0430\u0431 \u0438\u0437 \u0442\u0443\u0440\u0435\u0446\u043a\u043e\u0433\u043e \u0433\u043e\u0440\u043e\u0434\u0430 \u0410\u0434\u0430\u043d\u0430: \u0440\u0443\u0431\u043b\u0435\u043d\u0430\u044f \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0430 \u0441 \u043a\u0443\u0440\u0434\u044e\u0447\u043d\u044b\u043c \u0436\u0438\u0440\u043e\u043c, \u043f\u0435\u0440\u0446\u0435\u043c \u043f\u0443\u043b \u0431\u0438\u0431\u0435\u0440 \u0438 \u0442\u0451\u043f\u043b\u044b\u043c\u0438 \u0441\u043f\u0435\u0446\u0438\u044f\u043c\u0438, \u0432\u044b\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u0434\u043e \u043b\u0438\u043f\u043a\u043e\u0441\u0442\u0438 \u0438 \u0432\u044b\u043b\u0435\u043f\u043b\u0435\u043d\u043d\u0430\u044f \u043d\u0430 \u0448\u0438\u0440\u043e\u043a\u0438\u0435 \u0448\u0430\u043c\u043f\u0443\u0440\u044b. \u0416\u0430\u0440\u0438\u0442\u0441\u044f \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u044b\u0445 \u0443\u0433\u043b\u044f\u0445 \u0434\u043e \u0434\u044b\u043c\u043d\u043e\u0439 \u043a\u043e\u0440\u043e\u0447\u043a\u0438 \u0438 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0441\u043e\u0447\u043d\u044b\u043c \u0432\u043d\u0443\u0442\u0440\u0438. \u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0442\u0451\u043f\u043b\u044b\u043c \u043b\u0430\u0432\u0430\u0448\u0435\u043c, \u043f\u0435\u0447\u0451\u043d\u044b\u043c\u0438 \u043f\u043e\u043c\u0438\u0434\u043e\u0440\u0430\u043c\u0438, \u0437\u0435\u043b\u0451\u043d\u044b\u043c \u043f\u0435\u0440\u0446\u0435\u043c \u0438 \u043b\u0443\u043a\u043e\u043c \u0441 \u0441\u0443\u043c\u0430\u0445\u043e\u043c.","en":"The iconic kebab from the Turkish city of Adana: minced lamb with lamb fat, pul biber chili flakes and warm spices, kneaded until sticky and moulded onto wide metal skewers. Charred over very hot coals until smoky outside and juicy within. Serve with warm lavash, charred tomatoes, green peppers and red onion with sumac.","ua":"\u0417\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u0438\u0439 \u043a\u0435\u0431\u0430\u0431 \u0456\u0437 \u0442\u0443\u0440\u0435\u0446\u044c\u043a\u043e\u0433\u043e \u043c\u0456\u0441\u0442\u0430 \u0410\u0434\u0430\u043d\u0430: \u0440\u0443\u0431\u043b\u0435\u043d\u0430 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0430 \u0437 \u043a\u0443\u0440\u0434\u044e\u0447\u043d\u0438\u043c \u0436\u0438\u0440\u043e\u043c, \u043f\u0435\u0440\u0446\u0435\u043c \u043f\u0443\u043b \u0431\u0456\u0431\u0435\u0440 \u0456 \u0442\u0435\u043f\u043b\u0438\u043c\u0438 \u0441\u043f\u0435\u0446\u0456\u044f\u043c\u0438, \u0432\u0438\u043c\u0456\u0448\u0430\u043d\u0430 \u0434\u043e \u043b\u0438\u043f\u043a\u043e\u0441\u0442\u0456 \u0439 \u0432\u0438\u043b\u0456\u043f\u043b\u0435\u043d\u0430 \u043d\u0430 \u0448\u0438\u0440\u043e\u043a\u0456 \u0448\u0430\u043c\u043f\u0443\u0440\u0438. \u0421\u043c\u0430\u0436\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c\u0443 \u0436\u0430\u0440\u0456 \u0434\u043e \u0434\u0438\u043c\u043d\u043e\u0457 \u0441\u043a\u043e\u0440\u0438\u043d\u043a\u0438 \u0439 \u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u0441\u043e\u043a\u043e\u0432\u0438\u0442\u0438\u043c \u0443\u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0456. \u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0437 \u0442\u0435\u043f\u043b\u0438\u043c \u043b\u0430\u0432\u0430\u0448\u0435\u043c, \u043f\u0435\u0447\u0435\u043d\u0438\u043c\u0438 \u043f\u043e\u043c\u0456\u0434\u043e\u0440\u0430\u043c\u0438, \u0437\u0435\u043b\u0435\u043d\u0438\u043c \u043f\u0435\u0440\u0446\u0435\u043c \u0456 \u0446\u0438\u0431\u0443\u043b\u0435\u044e \u0456\u0437 \u0441\u0443\u043c\u0430\u0445\u043e\u043c."}$j$::jsonb, ingredients = $j${"ru":["\u0411\u0430\u0440\u0430\u043d\u0438\u043d\u0430 (\u043b\u043e\u043f\u0430\u0442\u043a\u0430 \u0438\u043b\u0438 \u0448\u0435\u044f) \u2014 800 \u0433","\u041a\u0443\u0440\u0434\u044e\u0447\u043d\u044b\u0439 \u0436\u0438\u0440 \u2014 150 \u0433","\u041b\u0443\u043a \u2014 1 \u0448\u0442","\u0427\u0435\u0441\u043d\u043e\u043a \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0430","\u0425\u043b\u043e\u043f\u044c\u044f \u043a\u0440\u0430\u0441\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0446\u0430 (\u043f\u0443\u043b \u0431\u0438\u0431\u0435\u0440) \u2014 2 \u0447. \u043b.","\u0421\u043b\u0430\u0434\u043a\u0430\u044f \u043f\u0430\u043f\u0440\u0438\u043a\u0430 \u2014 2 \u0447. \u043b.","\u0417\u0438\u0440\u0430 \u2014 1 \u0447. \u043b.","\u041c\u043e\u043b\u043e\u0442\u044b\u0439 \u043a\u043e\u0440\u0438\u0430\u043d\u0434\u0440 \u2014 1 \u0447. \u043b.","\u0427\u0451\u0440\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0446 \u2014 \u00bd \u0447. \u043b.","\u0421\u043e\u043b\u044c \u2014 1\u00bd \u0447. \u043b."],"en":["Lamb (shoulder or neck) \u2014 800 g","Lamb fat \u2014 150 g","Onion \u2014 1 piece","Garlic cloves \u2014 3 pieces","Red pepper flakes (pul biber) \u2014 2 tsp","Sweet paprika \u2014 2 tsp","Cumin \u2014 1 tsp","Ground coriander \u2014 1 tsp","Black pepper \u2014 \u00bd tsp","Salt \u2014 1\u00bd tsp"],"ua":["\u0411\u0430\u0440\u0430\u043d\u0438\u043d\u0430 (\u043b\u043e\u043f\u0430\u0442\u043a\u0430 \u0430\u0431\u043e \u0448\u0438\u044f) \u2014 800 \u0433","\u041a\u0443\u0440\u0434\u044e\u0447\u043d\u0438\u0439 \u0436\u0438\u0440 \u2014 150 \u0433","\u0426\u0438\u0431\u0443\u043b\u044f \u2014 1 \u0448\u0442","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u041f\u043b\u0430\u0441\u0442\u0456\u0432\u0446\u0456 \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u0433\u043e \u043f\u0435\u0440\u0446\u044e (\u043f\u0443\u043b \u0431\u0456\u0431\u0435\u0440) \u2014 2 \u0447. \u043b.","\u0421\u043e\u043b\u043e\u0434\u043a\u0430 \u043f\u0430\u043f\u0440\u0438\u043a\u0430 \u2014 2 \u0447. \u043b.","\u0417\u0456\u0440\u0430 \u2014 1 \u0447. \u043b.","\u041c\u0435\u043b\u0435\u043d\u0438\u0439 \u043a\u043e\u0440\u0456\u0430\u043d\u0434\u0440 \u2014 1 \u0447. \u043b.","\u0427\u043e\u0440\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 \u00bd \u0447. \u043b.","\u0421\u0456\u043b\u044c \u2014 1\u00bd \u0447. \u043b."]}$j$::jsonb, steps = $j${"ru":["\u041c\u0435\u043b\u043a\u043e \u043f\u043e\u0440\u0443\u0431\u0438\u0442\u0435 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0443 \u0441 \u0436\u0438\u0440\u043e\u043c \u043d\u043e\u0436\u043e\u043c \u0438\u043b\u0438 \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0438\u0442\u0435 \u0447\u0435\u0440\u0435\u0437 \u043c\u044f\u0441\u043e\u0440\u0443\u0431\u043a\u0443 \u0441 \u043a\u0440\u0443\u043f\u043d\u043e\u0439 \u0440\u0435\u0448\u0451\u0442\u043a\u043e\u0439.","\u041d\u0430\u0442\u0440\u0438\u0442\u0435 \u043b\u0443\u043a, \u043e\u0442\u043e\u0436\u043c\u0438\u0442\u0435 \u0441\u043e\u043a \u0438 \u0434\u043e\u0431\u0430\u0432\u044c\u0442\u0435 \u043a \u043c\u044f\u0441\u0443 \u0432\u043c\u0435\u0441\u0442\u0435 \u0441 \u0438\u0437\u043c\u0435\u043b\u044c\u0447\u0451\u043d\u043d\u044b\u043c \u0447\u0435\u0441\u043d\u043e\u043a\u043e\u043c \u0438 \u0432\u0441\u0435\u043c\u0438 \u0441\u043f\u0435\u0446\u0438\u044f\u043c\u0438.","\u0412\u044b\u043c\u0435\u0448\u0438\u0432\u0430\u0439\u0442\u0435 \u0444\u0430\u0440\u0448 10\u201315 \u043c\u0438\u043d\u0443\u0442, \u043f\u043e\u043a\u0430 \u043e\u043d \u043d\u0435 \u0441\u0442\u0430\u043d\u0435\u0442 \u043b\u0438\u043f\u043a\u0438\u043c \u0438 \u043e\u0434\u043d\u043e\u0440\u043e\u0434\u043d\u044b\u043c.","\u0423\u0431\u0435\u0440\u0438\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a \u043d\u0430 1 \u0447\u0430\u0441.","\u041c\u043e\u043a\u0440\u044b\u043c\u0438 \u0440\u0443\u043a\u0430\u043c\u0438 \u0440\u0430\u0432\u043d\u043e\u043c\u0435\u0440\u043d\u043e \u0432\u044b\u043b\u0435\u043f\u0438\u0442\u0435 \u0444\u0430\u0440\u0448 \u0432\u043e\u043a\u0440\u0443\u0433 \u0448\u0438\u0440\u043e\u043a\u0438\u0445 \u043c\u0435\u0442\u0430\u043b\u043b\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0448\u0430\u043c\u043f\u0443\u0440\u043e\u0432.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430\u0434 \u043e\u0447\u0435\u043d\u044c \u0433\u043e\u0440\u044f\u0447\u0438\u043c\u0438 \u0443\u0433\u043b\u044f\u043c\u0438 8\u201310 \u043c\u0438\u043d\u0443\u0442, \u0447\u0430\u0441\u0442\u043e \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f.","\u0420\u044f\u0434\u043e\u043c \u043d\u0430 \u0440\u0435\u0448\u0451\u0442\u043a\u0435 \u043e\u0431\u0436\u0430\u0440\u044c\u0442\u0435 \u043f\u043e\u043c\u0438\u0434\u043e\u0440\u044b \u0438 \u0437\u0435\u043b\u0451\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0446.","\u0421\u043b\u0435\u0433\u043a\u0430 \u043f\u0440\u043e\u0433\u0440\u0435\u0439\u0442\u0435 \u043b\u0430\u0432\u0430\u0448 \u0438 \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043a\u0435\u0431\u0430\u0431 \u0441 \u043e\u0432\u043e\u0449\u0430\u043c\u0438, \u043a\u0440\u0430\u0441\u043d\u044b\u043c \u043b\u0443\u043a\u043e\u043c \u0441 \u0441\u0443\u043c\u0430\u0445\u043e\u043c \u0438 \u043f\u0435\u0442\u0440\u0443\u0448\u043a\u043e\u0439. \u0413\u043b\u0430\u0432\u043d\u043e\u0435 \u2014 \u0445\u043e\u0440\u043e\u0448\u043e \u0432\u044b\u043c\u0435\u0441\u0438\u0442\u044c \u0444\u0430\u0440\u0448: \u0442\u043e\u043b\u044c\u043a\u043e \u0442\u043e\u0433\u0434\u0430 \u043e\u043d \u0434\u0435\u0440\u0436\u0438\u0442\u0441\u044f \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u0435."],"en":["Chop the lamb and fat very finely with a knife or pass them through a coarse mincer plate.","Grate the onion, squeeze out the juice and add it to the meat with the crushed garlic and all the spices.","Knead the mixture for 10\u201315 minutes until sticky and cohesive.","Chill for 1 hour.","With wet hands, mould the mixture evenly around wide metal skewers.","Grill over very hot coals for 8\u201310 minutes, turning often.","Char tomatoes and green peppers alongside.","Warm the lavash briefly and serve the kebab with the vegetables, red onion with sumac and fresh parsley. Proper kneading is the key \u2014 it is what makes the mixture hold on the skewer."],"ua":["\u0414\u0440\u0456\u0431\u043d\u043e \u043f\u043e\u0440\u0443\u0431\u0430\u0439\u0442\u0435 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0443 \u0437 \u0436\u0438\u0440\u043e\u043c \u043d\u043e\u0436\u0435\u043c \u0430\u0431\u043e \u043f\u0440\u043e\u043f\u0443\u0441\u0442\u0456\u0442\u044c \u0447\u0435\u0440\u0435\u0437 \u043c'\u044f\u0441\u043e\u0440\u0443\u0431\u043a\u0443 \u0437 \u0432\u0435\u043b\u0438\u043a\u043e\u044e \u0440\u0435\u0448\u0456\u0442\u043a\u043e\u044e.","\u041d\u0430\u0442\u0440\u0456\u0442\u044c \u0446\u0438\u0431\u0443\u043b\u044e, \u0432\u0456\u0434\u0456\u0436\u043c\u0456\u0442\u044c \u0441\u0456\u043a \u0456 \u0434\u043e\u0434\u0430\u0439\u0442\u0435 \u0434\u043e \u043c'\u044f\u0441\u0430 \u0440\u0430\u0437\u043e\u043c \u0456\u0437 \u043f\u043e\u0434\u0440\u0456\u0431\u043d\u0435\u043d\u0438\u043c \u0447\u0430\u0441\u043d\u0438\u043a\u043e\u043c \u0456 \u0432\u0441\u0456\u043c\u0430 \u0441\u043f\u0435\u0446\u0456\u044f\u043c\u0438.","\u0412\u0438\u043c\u0456\u0448\u0443\u0439\u0442\u0435 \u0444\u0430\u0440\u0448 10\u201315 \u0445\u0432\u0438\u043b\u0438\u043d, \u043f\u043e\u043a\u0438 \u0432\u0456\u043d \u043d\u0435 \u0441\u0442\u0430\u043d\u0435 \u043b\u0438\u043f\u043a\u0438\u043c \u0456 \u043e\u0434\u043d\u043e\u0440\u0456\u0434\u043d\u0438\u043c.","\u041f\u043e\u0441\u0442\u0430\u0432\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a \u043d\u0430 1 \u0433\u043e\u0434\u0438\u043d\u0443.","\u041c\u043e\u043a\u0440\u0438\u043c\u0438 \u0440\u0443\u043a\u0430\u043c\u0438 \u0440\u0456\u0432\u043d\u043e\u043c\u0456\u0440\u043d\u043e \u0432\u0438\u043b\u0456\u043f\u0456\u0442\u044c \u0444\u0430\u0440\u0448 \u043d\u0430\u0432\u043a\u043e\u043b\u043e \u0448\u0438\u0440\u043e\u043a\u0438\u0445 \u043c\u0435\u0442\u0430\u043b\u0435\u0432\u0438\u0445 \u0448\u0430\u043c\u043f\u0443\u0440\u0456\u0432.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430\u0434 \u0434\u0443\u0436\u0435 \u0433\u0430\u0440\u044f\u0447\u0438\u043c \u0432\u0443\u0433\u0456\u043b\u043b\u044f\u043c 8\u201310 \u0445\u0432\u0438\u043b\u0438\u043d, \u0447\u0430\u0441\u0442\u043e \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u0442\u0430\u044e\u0447\u0438.","\u041f\u043e\u0440\u0443\u0447 \u043d\u0430 \u0440\u0435\u0448\u0456\u0442\u0446\u0456 \u043e\u0431\u0441\u043c\u0430\u0436\u0442\u0435 \u043f\u043e\u043c\u0456\u0434\u043e\u0440\u0438 \u0439 \u0437\u0435\u043b\u0435\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c.","\u0417\u043b\u0435\u0433\u043a\u0430 \u043f\u0440\u043e\u0433\u0440\u0456\u0439\u0442\u0435 \u043b\u0430\u0432\u0430\u0448 \u0456 \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u043a\u0435\u0431\u0430\u0431 \u0437 \u043e\u0432\u043e\u0447\u0430\u043c\u0438, \u0447\u0435\u0440\u0432\u043e\u043d\u043e\u044e \u0446\u0438\u0431\u0443\u043b\u0435\u044e \u0456\u0437 \u0441\u0443\u043c\u0430\u0445\u043e\u043c \u0456 \u043f\u0435\u0442\u0440\u0443\u0448\u043a\u043e\u044e. \u0413\u043e\u043b\u043e\u0432\u043d\u0435 \u2014 \u0434\u043e\u0431\u0440\u0435 \u0432\u0438\u043c\u0456\u0441\u0438\u0442\u0438 \u0444\u0430\u0440\u0448: \u0442\u0456\u043b\u044c\u043a\u0438 \u0442\u043e\u0434\u0456 \u0432\u0456\u043d \u0442\u0440\u0438\u043c\u0430\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u0456."]}$j$::jsonb, tags = $j${"ru":["\u0442\u0443\u0440\u0435\u0446\u043a\u0430\u044f \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0430","\u0441\u043f\u0435\u0446\u0438\u0438","\u043d\u0430 \u0443\u0433\u043b\u044f\u0445"],"en":["turkish cuisine","grilled","lamb","spiced","charcoal"],"ua":["\u0442\u0443\u0440\u0435\u0446\u044c\u043a\u0430 \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0430","\u0441\u043f\u0435\u0446\u0456\u0457","\u043d\u0430 \u0432\u0443\u0433\u0456\u043b\u043b\u0456"]}$j$::jsonb where slug = 'adana-kebab-turkish-spiced-beef-kebab' and not (title ? 'ua');
update recipes set title = $j${"ru":"\u041f\u0443\u043b\u044c\u043a\u043e\u0433\u0438 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0430\u0445 \u2014 \u043a\u043e\u0440\u0435\u0439\u0441\u043a\u0438\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0438\u0437 \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u044b","en":"Bulgogi Skewers \u2014 Korean Beef Kebabs","ua":"\u041f\u0443\u043b\u044c\u0433\u043e\u0433\u0456 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0430\u0445 \u2014 \u043a\u043e\u0440\u0435\u0439\u0441\u044c\u043a\u0456 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0437 \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0438"}$j$::jsonb, description = $j${"ru":"\u041d\u0435\u0436\u043d\u0430\u044f \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u0430 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0435 \u0438\u0437 \u0441\u043e\u0435\u0432\u043e\u0433\u043e \u0441\u043e\u0443\u0441\u0430, \u0442\u0451\u0440\u0442\u043e\u0439 \u0433\u0440\u0443\u0448\u0438, \u0447\u0435\u0441\u043d\u043e\u043a\u0430 \u0438 \u0438\u043c\u0431\u0438\u0440\u044f, \u043e\u0431\u0436\u0430\u0440\u0435\u043d\u043d\u0430\u044f \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c \u043e\u0433\u043d\u0435 \u0434\u043e \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u044c\u043d\u043e\u0439 \u043a\u043e\u0440\u043e\u0447\u043a\u0438. \u0413\u0440\u0443\u0448\u0430 \u0434\u0435\u043b\u0430\u0435\u0442 \u043c\u044f\u0441\u043e \u043c\u044f\u0433\u043a\u0438\u043c, \u0430 \u0441\u043e\u0443\u0441 \u0434\u0430\u0451\u0442 \u0431\u0430\u043b\u0430\u043d\u0441 \u0441\u043b\u0430\u0434\u043a\u043e\u0433\u043e, \u0441\u043e\u043b\u0451\u043d\u043e\u0433\u043e \u0438 \u0443\u043c\u0430\u043c\u0438. \u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0440\u0438\u0441\u043e\u043c \u0438 \u0441\u0432\u0435\u0436\u0438\u043c\u0438 \u043e\u0432\u043e\u0449\u0430\u043c\u0438.","en":"Tender beef marinated in soy sauce, grated pear, garlic and ginger, then seared over high heat until caramelised outside and juicy within. The pear softens the meat, the marinade balances sweet, salty and umami. Serve with steamed rice and fresh vegetables.","ua":"\u041d\u0456\u0436\u043d\u0430 \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0430 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0456 \u0456\u0437 \u0441\u043e\u0454\u0432\u043e\u0433\u043e \u0441\u043e\u0443\u0441\u0443, \u0442\u0435\u0440\u0442\u043e\u0457 \u0433\u0440\u0443\u0448\u0456, \u0447\u0430\u0441\u043d\u0438\u043a\u0443 \u0439 \u0456\u043c\u0431\u0438\u0440\u0443, \u043e\u0431\u0441\u043c\u0430\u0436\u0435\u043d\u0430 \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 \u0434\u043e \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u044c\u043d\u043e\u0457 \u0441\u043a\u043e\u0440\u0438\u043d\u043a\u0438. \u0413\u0440\u0443\u0448\u0430 \u0440\u043e\u0431\u0438\u0442\u044c \u043c'\u044f\u0441\u043e \u043c'\u044f\u043a\u0438\u043c, \u0430 \u0441\u043e\u0443\u0441 \u0434\u0430\u0454 \u0431\u0430\u043b\u0430\u043d\u0441 \u0441\u043e\u043b\u043e\u0434\u043a\u043e\u0433\u043e, \u0441\u043e\u043b\u043e\u043d\u043e\u0433\u043e \u0439 \u0443\u043c\u0430\u043c\u0456. \u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0437 \u0440\u0438\u0441\u043e\u043c \u0456 \u0441\u0432\u0456\u0436\u0438\u043c\u0438 \u043e\u0432\u043e\u0447\u0430\u043c\u0438."}$j$::jsonb, ingredients = $j${"ru":["\u0413\u043e\u0432\u044f\u0434\u0438\u043d\u0430 (\u0440\u0438\u0431\u0430\u0439 \u0438\u043b\u0438 \u0441\u0442\u0440\u0438\u043f\u043b\u043e\u0439\u043d) \u2014 800 \u0433","\u0421\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441 \u2014 100 \u043c\u043b","\u0413\u0440\u0443\u0448\u0430 \u2014 1 \u0448\u0442","\u0427\u0435\u0441\u043d\u043e\u043a \u2014 4 \u0437\u0443\u0431\u0447\u0438\u043a\u0430","\u0422\u0451\u0440\u0442\u044b\u0439 \u0438\u043c\u0431\u0438\u0440\u044c \u2014 1 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u044b\u0439 \u0441\u0430\u0445\u0430\u0440 \u2014 1 \u0441\u0442. \u043b.","\u041a\u0443\u043d\u0436\u0443\u0442\u043d\u043e\u0435 \u043c\u0430\u0441\u043b\u043e \u2014 2 \u0441\u0442. \u043b.","\u0420\u0438\u0441\u043e\u0432\u044b\u0439 \u0443\u043a\u0441\u0443\u0441 \u2014 1 \u0441\u0442. \u043b.","\u0427\u0451\u0440\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0446 \u2014 \u00bd \u0447. \u043b.","\u041a\u0443\u043d\u0436\u0443\u0442 \u2014 1 \u0441\u0442. \u043b.","\u0417\u0435\u043b\u0451\u043d\u044b\u0439 \u043b\u0443\u043a \u2014 2 \u0441\u0442\u0435\u0431\u043b\u044f"],"en":["Beef (ribeye or strip steak) \u2014 800 g","Soy sauce \u2014 100 ml","Pear \u2014 1 piece","Garlic cloves \u2014 4 pieces","Grated ginger \u2014 1 tbsp","Brown sugar \u2014 1 tbsp","Sesame oil \u2014 2 tbsp","Rice vinegar \u2014 1 tbsp","Black pepper \u2014 \u00bd tsp","Sesame seeds \u2014 1 tbsp","Green onions \u2014 2 stalks"],"ua":["\u042f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0430 (\u0440\u0438\u0431\u0430\u0439 \u0430\u0431\u043e \u0441\u0442\u0440\u0438\u043f\u043b\u043e\u0439\u043d) \u2014 800 \u0433","\u0421\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441 \u2014 100 \u043c\u043b","\u0413\u0440\u0443\u0448\u0430 \u2014 1 \u0448\u0442","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 4 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u0422\u0435\u0440\u0442\u0438\u0439 \u0456\u043c\u0431\u0438\u0440 \u2014 1 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u0438\u0439 \u0446\u0443\u043a\u043e\u0440 \u2014 1 \u0441\u0442. \u043b.","\u041a\u0443\u043d\u0436\u0443\u0442\u043d\u0430 \u043e\u043b\u0456\u044f \u2014 2 \u0441\u0442. \u043b.","\u0420\u0438\u0441\u043e\u0432\u0438\u0439 \u043e\u0446\u0435\u0442 \u2014 1 \u0441\u0442. \u043b.","\u0427\u043e\u0440\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 \u00bd \u0447. \u043b.","\u041a\u0443\u043d\u0436\u0443\u0442 \u2014 1 \u0441\u0442. \u043b.","\u0417\u0435\u043b\u0435\u043d\u0430 \u0446\u0438\u0431\u0443\u043b\u044f \u2014 2 \u0441\u0442\u0435\u0431\u043b\u0430"]}$j$::jsonb, steps = $j${"ru":["\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u0443 \u043f\u043e\u043f\u0435\u0440\u0451\u043a \u0432\u043e\u043b\u043e\u043a\u043e\u043d \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u043f\u043b\u0430\u0441\u0442\u0430\u043c\u0438 \u0442\u043e\u043b\u0449\u0438\u043d\u043e\u0439 5\u20137 \u043c\u043c.","\u041d\u0430\u0442\u0440\u0438\u0442\u0435 \u0433\u0440\u0443\u0448\u0443, \u0438\u0437\u043c\u0435\u043b\u044c\u0447\u0438\u0442\u0435 \u0447\u0435\u0441\u043d\u043e\u043a \u0438 \u0441\u043c\u0435\u0448\u0430\u0439\u0442\u0435 \u0432 \u0433\u043b\u0443\u0431\u043e\u043a\u043e\u0439 \u043c\u0438\u0441\u043a\u0435 \u0441\u043e \u0432\u0441\u0435\u043c\u0438 \u0438\u043d\u0433\u0440\u0435\u0434\u0438\u0435\u043d\u0442\u0430\u043c\u0438 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0430.","\u0417\u0430\u043c\u0430\u0440\u0438\u043d\u0443\u0439\u0442\u0435 \u043c\u044f\u0441\u043e \u043d\u0430 4\u20138 \u0447\u0430\u0441\u043e\u0432 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0435.","\u041d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043f\u043e\u043b\u043e\u0441\u043a\u0438 \u043c\u044f\u0441\u0430 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u0433\u0430\u0440\u043c\u043e\u0448\u043a\u043e\u0439.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c \u043e\u0433\u043d\u0435 \u0438\u043b\u0438 \u043d\u0430 \u0440\u0430\u0441\u043a\u0430\u043b\u0451\u043d\u043d\u043e\u0439 \u0441\u043a\u043e\u0432\u043e\u0440\u043e\u0434\u0435-\u0433\u0440\u0438\u043b\u044c \u043f\u043e 2\u20133 \u043c\u0438\u043d\u0443\u0442\u044b \u0441 \u043a\u0430\u0436\u0434\u043e\u0439 \u0441\u0442\u043e\u0440\u043e\u043d\u044b.","\u0412\u043e \u0432\u0440\u0435\u043c\u044f \u0436\u0430\u0440\u043a\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u0441\u043c\u0430\u0436\u044c\u0442\u0435 \u043c\u044f\u0441\u043e \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c.","\u0414\u0430\u0439\u0442\u0435 \u043c\u044f\u0441\u0443 \u043e\u0442\u0434\u043e\u0445\u043d\u0443\u0442\u044c 2 \u043c\u0438\u043d\u0443\u0442\u044b.","\u041f\u043e\u0441\u044b\u043f\u044c\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0438 \u0437\u0435\u043b\u0451\u043d\u044b\u043c \u043b\u0443\u043a\u043e\u043c. \u0416\u0430\u0440\u044c\u0442\u0435 \u043f\u0430\u0440\u0442\u0438\u044f\u043c\u0438 \u0438 \u043d\u0435 \u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u0432\u043f\u043b\u043e\u0442\u043d\u0443\u044e \u2014 \u0438\u043d\u0430\u0447\u0435 \u043c\u044f\u0441\u043e \u0442\u0443\u0448\u0438\u0442\u0441\u044f, \u0430 \u043d\u0435 \u043e\u0431\u0436\u0430\u0440\u0438\u0432\u0430\u0435\u0442\u0441\u044f."],"en":["Slice the beef thinly against the grain, 5\u20137 mm thick.","Grate the pear, crush the garlic and whisk them in a deep bowl with all the other marinade ingredients.","Marinate the meat in the fridge for 4\u20138 hours.","Thread the strips onto skewers in a ribbon.","Grill over high heat or sear in a very hot grill pan for 2\u20133 minutes per side.","Baste with the marinade a few times while cooking.","Let the meat rest for 2 minutes.","Sprinkle with sesame seeds and green onions. Cook in batches and leave space between the skewers, or the meat steams instead of searing."],"ua":["\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0443 \u0432\u043f\u043e\u043f\u0435\u0440\u0435\u043a \u0432\u043e\u043b\u043e\u043a\u043e\u043d \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u043f\u043b\u0430\u0441\u0442\u0438\u043d\u0430\u043c\u0438 \u0437\u0430\u0432\u0442\u043e\u0432\u0448\u043a\u0438 5\u20137 \u043c\u043c.","\u041d\u0430\u0442\u0440\u0456\u0442\u044c \u0433\u0440\u0443\u0448\u0443, \u043f\u043e\u0434\u0440\u0456\u0431\u043d\u0456\u0442\u044c \u0447\u0430\u0441\u043d\u0438\u043a \u0456 \u0437\u043c\u0456\u0448\u0430\u0439\u0442\u0435 \u0432 \u0433\u043b\u0438\u0431\u043e\u043a\u0456\u0439 \u043c\u0438\u0441\u0446\u0456 \u0437 \u0443\u0441\u0456\u043c\u0430 \u0456\u043d\u0433\u0440\u0435\u0434\u0456\u0454\u043d\u0442\u0430\u043c\u0438 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0443.","\u0417\u0430\u043c\u0430\u0440\u0438\u043d\u0443\u0439\u0442\u0435 \u043c'\u044f\u0441\u043e \u043d\u0430 4\u20138 \u0433\u043e\u0434\u0438\u043d \u0443 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0443.","\u041d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u0441\u043c\u0443\u0436\u043a\u0438 \u043c'\u044f\u0441\u0430 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u0433\u0430\u0440\u043c\u043e\u0448\u043a\u043e\u044e.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 \u0430\u0431\u043e \u043d\u0430 \u0440\u043e\u0437\u043f\u0435\u0447\u0435\u043d\u0456\u0439 \u0441\u043a\u043e\u0432\u043e\u0440\u043e\u0434\u0456-\u0433\u0440\u0438\u043b\u044c \u043f\u043e 2\u20133 \u0445\u0432\u0438\u043b\u0438\u043d\u0438 \u0437 \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0431\u043e\u043a\u0443.","\u041f\u0456\u0434 \u0447\u0430\u0441 \u0441\u043c\u0430\u0436\u0435\u043d\u043d\u044f \u043a\u0456\u043b\u044c\u043a\u0430 \u0440\u0430\u0437\u0456\u0432 \u0437\u043c\u0430\u0441\u0442\u0456\u0442\u044c \u043c'\u044f\u0441\u043e \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c.","\u0414\u0430\u0439\u0442\u0435 \u043c'\u044f\u0441\u0443 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u0442\u0438 2 \u0445\u0432\u0438\u043b\u0438\u043d\u0438.","\u041f\u043e\u0441\u0438\u043f\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0456 \u0437\u0435\u043b\u0435\u043d\u043e\u044e \u0446\u0438\u0431\u0443\u043b\u0435\u044e. \u0421\u043c\u0430\u0436\u0442\u0435 \u043f\u0430\u0440\u0442\u0456\u044f\u043c\u0438 \u0439 \u043d\u0435 \u0441\u0442\u0430\u0432\u0442\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u0432\u043f\u0440\u0438\u0442\u0443\u043b \u2014 \u0456\u043d\u0430\u043a\u0448\u0435 \u043c'\u044f\u0441\u043e \u0442\u0443\u0448\u043a\u0443\u0454\u0442\u044c\u0441\u044f, \u0430 \u043d\u0435 \u043e\u0431\u0441\u043c\u0430\u0436\u0443\u0454\u0442\u044c\u0441\u044f."]}$j$::jsonb, tags = $j${"ru":["\u043a\u043e\u0440\u0435\u0439\u0441\u043a\u0430\u044f \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u043c\u0430\u0440\u0438\u043d\u0430\u0434","\u043f\u0440\u0430\u0437\u0434\u043d\u0438\u0447\u043d\u043e\u0435 \u0431\u043b\u044e\u0434\u043e","\u0433\u043e\u0432\u044f\u0434\u0438\u043d\u0430"],"en":["korean cuisine","grilled","marinated","festive dish","beef"],"ua":["\u043a\u043e\u0440\u0435\u0439\u0441\u044c\u043a\u0430 \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u043c\u0430\u0440\u0438\u043d\u0430\u0434","\u0441\u0432\u044f\u0442\u043a\u043e\u0432\u0430 \u0441\u0442\u0440\u0430\u0432\u0430","\u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0430"]}$j$::jsonb where slug = 'bulgogi-skewers-korean-beef-kebabs' and not (title ? 'ua');
update recipes set title = $j${"ru":"\u0427\u0443\u0440\u0440\u0430\u0441\u043a\u043e \u2014 \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0438\u0439 \u0448\u0430\u0448\u043b\u044b\u043a \u0438\u0437 \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u044b","en":"Churrasco \u2014 Brazilian Grilled Beef Skewers","ua":"\u0427\u0443\u0440\u0430\u0441\u043a\u043e \u2014 \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u044c\u043a\u0438\u0439 \u0448\u0430\u0448\u043b\u0438\u043a \u0437 \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0438"}$j$::jsonb, description = $j${"ru":"\u0413\u043e\u0440\u0434\u043e\u0441\u0442\u044c \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u043a\u0438\u0445 \u0447\u0443\u0440\u0440\u0430\u0441\u043a\u0430\u0440\u0438\u0439: \u0442\u043e\u043b\u0441\u0442\u044b\u0435 \u043a\u0443\u0441\u043a\u0438 \u043f\u0438\u043a\u0430\u043d\u044c\u0438 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u0435, \u043e\u0431\u0436\u0430\u0440\u0435\u043d\u043d\u044b\u0435 \u043d\u0430 \u043e\u0442\u043a\u0440\u044b\u0442\u043e\u043c \u043e\u0433\u043d\u0435 \u0434\u043e \u0445\u0440\u0443\u0441\u0442\u044f\u0449\u0435\u0439 \u043a\u043e\u0440\u043e\u0447\u043a\u0438 \u0438 \u0440\u043e\u0437\u043e\u0432\u043e\u0439 \u0441\u043e\u0447\u043d\u043e\u0439 \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u044b. \u0422\u043e\u043b\u044c\u043a\u043e \u043a\u0440\u0443\u043f\u043d\u0430\u044f \u0441\u043e\u043b\u044c \u2014 \u043d\u0438\u0447\u0442\u043e \u043d\u0435 \u0441\u043f\u043e\u0440\u0438\u0442 \u0441\u043e \u0432\u043a\u0443\u0441\u043e\u043c \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u044b. \u041c\u044f\u0441\u043e \u0441\u0440\u0435\u0437\u0430\u044e\u0442 \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u043b\u043e\u043c\u0442\u0438\u043a\u0430\u043c\u0438 \u043f\u0440\u044f\u043c\u043e \u0441 \u0448\u0430\u043c\u043f\u0443\u0440\u0430 \u0438 \u043f\u043e\u0434\u0430\u044e\u0442 \u0441 \u044f\u0440\u043a\u0438\u043c \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438 \u0438 \u0445\u043b\u0435\u0431\u043e\u043c.","en":"The pride of Brazilian churrascarias: thick pieces of picanha on a skewer, grilled over open flame until charred outside and pink and juicy inside. Only coarse salt, so nothing competes with the beef. The meat is carved thinly straight off the skewer and served with bright chimichurri and crusty bread.","ua":"\u0413\u043e\u0440\u0434\u0456\u0441\u0442\u044c \u0431\u0440\u0430\u0437\u0438\u043b\u044c\u0441\u044c\u043a\u0438\u0445 \u0447\u0443\u0440\u0430\u0441\u043a\u0430\u0440\u0456\u0439: \u0442\u043e\u0432\u0441\u0442\u0456 \u0448\u043c\u0430\u0442\u043a\u0438 \u043f\u0456\u043a\u0430\u043d\u044c\u0457 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u0456, \u043e\u0431\u0441\u043c\u0430\u0436\u0435\u043d\u0456 \u043d\u0430 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 \u0434\u043e \u0445\u0440\u0443\u0441\u0442\u043a\u043e\u0457 \u0441\u043a\u043e\u0440\u0438\u043d\u043a\u0438 \u0439 \u0440\u043e\u0436\u0435\u0432\u043e\u0457 \u0441\u043e\u043a\u043e\u0432\u0438\u0442\u043e\u0457 \u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0438. \u041b\u0438\u0448\u0435 \u043a\u0440\u0443\u043f\u043d\u0430 \u0441\u0456\u043b\u044c \u2014 \u043d\u0456\u0449\u043e \u043d\u0435 \u0441\u043f\u0435\u0440\u0435\u0447\u0430\u0454\u0442\u044c\u0441\u044f \u0437\u0456 \u0441\u043c\u0430\u043a\u043e\u043c \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0438. \u041c'\u044f\u0441\u043e \u0437\u0440\u0456\u0437\u0430\u044e\u0442\u044c \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u0441\u043a\u0438\u0431\u043a\u0430\u043c\u0438 \u043f\u0440\u043e\u0441\u0442\u043e \u0437 \u0448\u0430\u043c\u043f\u0443\u0440\u0430 \u0439 \u043f\u043e\u0434\u0430\u044e\u0442\u044c \u0437 \u044f\u0441\u043a\u0440\u0430\u0432\u0438\u043c \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456 \u0442\u0430 \u0445\u043b\u0456\u0431\u043e\u043c."}$j$::jsonb, ingredients = $j${"ru":["\u0413\u043e\u0432\u044f\u0434\u0438\u043d\u0430: \u043f\u0438\u043a\u0430\u043d\u044c\u044f \u0438\u043b\u0438 \u0440\u0438\u0431\u0430\u0439 \u2014 1,5 \u043a\u0433","\u041a\u0440\u0443\u043f\u043d\u0430\u044f \u043c\u043e\u0440\u0441\u043a\u0430\u044f \u0441\u043e\u043b\u044c \u2014 2 \u0441\u0442. \u043b.","\u0427\u0451\u0440\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0446 \u2014 1 \u0447. \u043b. (\u043f\u043e \u0436\u0435\u043b\u0430\u043d\u0438\u044e)","\u041f\u0435\u0442\u0440\u0443\u0448\u043a\u0430 (\u0434\u043b\u044f \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438) \u2014 1 \u043f\u0443\u0447\u043e\u043a","\u0427\u0435\u0441\u043d\u043e\u043a (\u0434\u043b\u044f \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438) \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0430","\u041a\u0440\u0430\u0441\u043d\u044b\u0439 \u0432\u0438\u043d\u043d\u044b\u0439 \u0443\u043a\u0441\u0443\u0441 (\u0434\u043b\u044f \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438) \u2014 2 \u0441\u0442. \u043b.","\u041e\u043b\u0438\u0432\u043a\u043e\u0432\u043e\u0435 \u043c\u0430\u0441\u043b\u043e (\u0434\u043b\u044f \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438) \u2014 100 \u043c\u043b","\u0421\u0443\u0448\u0451\u043d\u044b\u0439 \u043e\u0440\u0435\u0433\u0430\u043d\u043e \u0438 \u0445\u043b\u043e\u043f\u044c\u044f \u0447\u0438\u043b\u0438 (\u0434\u043b\u044f \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438) \u2014 \u043f\u043e \u00bd \u0447. \u043b."],"en":["Beef picanha or ribeye \u2014 1.5 kg","Coarse sea salt \u2014 2 tbsp","Black pepper \u2014 1 tsp (optional)","Parsley (for chimichurri) \u2014 1 bunch","Garlic (for chimichurri) \u2014 3 cloves","Red wine vinegar (for chimichurri) \u2014 2 tbsp","Olive oil (for chimichurri) \u2014 100 ml","Dried oregano and chili flakes (for chimichurri) \u2014 \u00bd tsp each"],"ua":["\u042f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0430: \u043f\u0456\u043a\u0430\u043d\u044c\u044f \u0430\u0431\u043e \u0440\u0438\u0431\u0430\u0439 \u2014 1,5 \u043a\u0433","\u041a\u0440\u0443\u043f\u043d\u0430 \u043c\u043e\u0440\u0441\u044c\u043a\u0430 \u0441\u0456\u043b\u044c \u2014 2 \u0441\u0442. \u043b.","\u0427\u043e\u0440\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 1 \u0447. \u043b. (\u0437\u0430 \u0431\u0430\u0436\u0430\u043d\u043d\u044f\u043c)","\u041f\u0435\u0442\u0440\u0443\u0448\u043a\u0430 (\u0434\u043b\u044f \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456) \u2014 1 \u043f\u0443\u0447\u043e\u043a","\u0427\u0430\u0441\u043d\u0438\u043a (\u0434\u043b\u044f \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456) \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u0427\u0435\u0440\u0432\u043e\u043d\u0438\u0439 \u0432\u0438\u043d\u043d\u0438\u0439 \u043e\u0446\u0435\u0442 (\u0434\u043b\u044f \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456) \u2014 2 \u0441\u0442. \u043b.","\u041e\u043b\u0438\u0432\u043a\u043e\u0432\u0430 \u043e\u043b\u0456\u044f (\u0434\u043b\u044f \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456) \u2014 100 \u043c\u043b","\u0421\u0443\u0448\u0435\u043d\u0438\u0439 \u043e\u0440\u0435\u0433\u0430\u043d\u043e \u0439 \u043f\u043b\u0430\u0441\u0442\u0456\u0432\u0446\u0456 \u0447\u0438\u043b\u0456 (\u0434\u043b\u044f \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456) \u2014 \u043f\u043e \u00bd \u0447. \u043b."]}$j$::jsonb, steps = $j${"ru":["\u0414\u043e\u0441\u0442\u0430\u043d\u044c\u0442\u0435 \u043c\u044f\u0441\u043e \u0438\u0437 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0430 \u0437\u0430 40\u201360 \u043c\u0438\u043d\u0443\u0442 \u0434\u043e \u0436\u0430\u0440\u043a\u0438, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u043e \u043f\u0440\u043e\u0436\u0430\u0440\u0438\u043b\u043e\u0441\u044c \u0440\u0430\u0432\u043d\u043e\u043c\u0435\u0440\u043d\u043e.","\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u0433\u043e\u0432\u044f\u0434\u0438\u043d\u0443 \u043f\u043e\u043f\u0435\u0440\u0451\u043a \u0432\u043e\u043b\u043e\u043a\u043e\u043d \u0442\u043e\u043b\u0441\u0442\u044b\u043c\u0438 \u043a\u0443\u0441\u043a\u0430\u043c\u0438 \u043f\u043e 4\u20135 \u0441\u043c, \u043e\u0441\u0442\u0430\u0432\u0438\u0432 \u0436\u0438\u0440\u043e\u0432\u0443\u044e \u0448\u0430\u043f\u043a\u0443.","\u041d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043a\u0443\u0441\u043a\u0438 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440, \u0441\u043e\u0433\u043d\u0443\u0432 \u0438\u0445 \u043f\u043e\u0434\u043a\u043e\u0432\u043e\u0439 \u0436\u0438\u0440\u043e\u043c \u043d\u0430\u0440\u0443\u0436\u0443, \u0438 \u0449\u0435\u0434\u0440\u043e \u043f\u043e\u0441\u044b\u043f\u044c\u0442\u0435 \u043a\u0440\u0443\u043f\u043d\u043e\u0439 \u0441\u043e\u043b\u044c\u044e.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430\u0434 \u043e\u0447\u0435\u043d\u044c \u0433\u043e\u0440\u044f\u0447\u0438\u043c\u0438 \u0443\u0433\u043b\u044f\u043c\u0438 8\u201310 \u043c\u0438\u043d\u0443\u0442, \u043f\u043e\u0441\u0442\u043e\u044f\u043d\u043d\u043e \u043f\u043e\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f.","\u041f\u043e\u043a\u0430 \u043c\u044f\u0441\u043e \u0436\u0430\u0440\u0438\u0442\u0441\u044f, \u043f\u0440\u0438\u0433\u043e\u0442\u043e\u0432\u044c\u0442\u0435 \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438: \u043c\u0435\u043b\u043a\u043e \u043f\u043e\u0440\u0443\u0431\u0438\u0442\u0435 \u043f\u0435\u0442\u0440\u0443\u0448\u043a\u0443 \u0438 \u0447\u0435\u0441\u043d\u043e\u043a, \u0441\u043c\u0435\u0448\u0430\u0439\u0442\u0435 \u0441 \u0443\u043a\u0441\u0443\u0441\u043e\u043c, \u043c\u0430\u0441\u043b\u043e\u043c, \u043e\u0440\u0435\u0433\u0430\u043d\u043e \u0438 \u0447\u0438\u043b\u0438.","\u0421\u0440\u0435\u0436\u044c\u0442\u0435 \u043f\u0440\u043e\u0436\u0430\u0440\u0435\u043d\u043d\u044b\u0439 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0441\u043b\u043e\u0439 \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u043b\u043e\u043c\u0442\u0438\u043a\u0430\u043c\u0438 \u043d\u0430 \u0442\u0451\u043f\u043b\u0443\u044e \u0442\u0430\u0440\u0435\u043b\u043a\u0443.","\u0412\u0435\u0440\u043d\u0438\u0442\u0435 \u0448\u0430\u043c\u043f\u0443\u0440 \u043d\u0430 \u043e\u0433\u043e\u043d\u044c, \u0447\u0442\u043e\u0431\u044b \u0434\u043e\u0436\u0430\u0440\u0438\u0442\u044c \u0441\u043b\u0435\u0434\u0443\u044e\u0449\u0438\u0439 \u0441\u043b\u043e\u0439, \u0438 \u043f\u043e\u0432\u0442\u043e\u0440\u044f\u0439\u0442\u0435.","\u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0447\u0438\u043c\u0438\u0447\u0443\u0440\u0440\u0438, \u043f\u0435\u0447\u0451\u043d\u044b\u043c\u0438 \u043e\u0432\u043e\u0449\u0430\u043c\u0438 \u0438 \u0445\u0440\u0443\u0441\u0442\u044f\u0449\u0438\u043c \u0445\u043b\u0435\u0431\u043e\u043c."],"en":["Take the meat out of the fridge 40\u201360 minutes before grilling so it cooks evenly.","Cut the beef against the grain into thick pieces, 4\u20135 cm, keeping the fat cap on.","Thread the pieces onto a skewer bent into a C shape, fat side out, and season generously with coarse salt.","Grill over very hot coals for 8\u201310 minutes, turning constantly.","While the meat cooks, make the chimichurri: chop the parsley and garlic finely and mix with the vinegar, olive oil, oregano and chili.","Carve the cooked outer layer in thin slices onto a warm plate.","Return the skewer to the fire to cook the next layer, and repeat.","Serve with chimichurri, grilled vegetables and crusty bread."],"ua":["\u0414\u0456\u0441\u0442\u0430\u043d\u044c\u0442\u0435 \u043c'\u044f\u0441\u043e \u0437 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0430 \u0437\u0430 40\u201360 \u0445\u0432\u0438\u043b\u0438\u043d \u0434\u043e \u0441\u043c\u0430\u0436\u0435\u043d\u043d\u044f, \u0449\u043e\u0431 \u0432\u043e\u043d\u043e \u043f\u0440\u043e\u0441\u043c\u0430\u0436\u0438\u043b\u043e\u0441\u044f \u0440\u0456\u0432\u043d\u043e\u043c\u0456\u0440\u043d\u043e.","\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u044f\u043b\u043e\u0432\u0438\u0447\u0438\u043d\u0443 \u0432\u043f\u043e\u043f\u0435\u0440\u0435\u043a \u0432\u043e\u043b\u043e\u043a\u043e\u043d \u0442\u043e\u0432\u0441\u0442\u0438\u043c\u0438 \u0448\u043c\u0430\u0442\u043a\u0430\u043c\u0438 \u043f\u043e 4\u20135 \u0441\u043c, \u0437\u0430\u043b\u0438\u0448\u0438\u0432\u0448\u0438 \u0436\u0438\u0440\u043e\u0432\u0443 \u0448\u0430\u043f\u043a\u0443.","\u041d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u0448\u043c\u0430\u0442\u043a\u0438 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440, \u0437\u0456\u0433\u043d\u0443\u0432\u0448\u0438 \u0457\u0445 \u043f\u0456\u0434\u043a\u043e\u0432\u043e\u044e \u0436\u0438\u0440\u043e\u043c \u043d\u0430\u0437\u043e\u0432\u043d\u0456, \u0456 \u0449\u0435\u0434\u0440\u043e \u043f\u043e\u0441\u0438\u043f\u0442\u0435 \u043a\u0440\u0443\u043f\u043d\u043e\u044e \u0441\u0456\u043b\u043b\u044e.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430\u0434 \u0434\u0443\u0436\u0435 \u0433\u0430\u0440\u044f\u0447\u0438\u043c \u0432\u0443\u0433\u0456\u043b\u043b\u044f\u043c 8\u201310 \u0445\u0432\u0438\u043b\u0438\u043d, \u043f\u043e\u0441\u0442\u0456\u0439\u043d\u043e \u043f\u043e\u0432\u0435\u0440\u0442\u0430\u044e\u0447\u0438.","\u041f\u043e\u043a\u0438 \u043c'\u044f\u0441\u043e \u0441\u043c\u0430\u0436\u0438\u0442\u044c\u0441\u044f, \u043f\u0440\u0438\u0433\u043e\u0442\u0443\u0439\u0442\u0435 \u0447\u0438\u043c\u0456\u0447\u0443\u0440\u0456: \u0434\u0440\u0456\u0431\u043d\u043e \u043f\u043e\u0441\u0456\u0447\u0456\u0442\u044c \u043f\u0435\u0442\u0440\u0443\u0448\u043a\u0443 \u0439 \u0447\u0430\u0441\u043d\u0438\u043a, \u0437\u043c\u0456\u0448\u0430\u0439\u0442\u0435 \u0437 \u043e\u0446\u0442\u043e\u043c, \u043e\u043b\u0456\u0454\u044e, \u043e\u0440\u0435\u0433\u0430\u043d\u043e \u0439 \u0447\u0438\u043b\u0456.","\u0417\u0440\u0456\u0436\u0442\u0435 \u043f\u0440\u043e\u0441\u043c\u0430\u0436\u0435\u043d\u0438\u0439 \u0437\u043e\u0432\u043d\u0456\u0448\u043d\u0456\u0439 \u0448\u0430\u0440 \u0442\u043e\u043d\u043a\u0438\u043c\u0438 \u0441\u043a\u0438\u0431\u043a\u0430\u043c\u0438 \u043d\u0430 \u0442\u0435\u04