update recipes set title = $j${"ru":"\u041a\u0443\u0440\u0438\u0446\u0430 \u0445\u0443\u043b\u0438-\u0445\u0443\u043b\u0438","en":"Huli Huli Chicken","ua":"\u041a\u0443\u0440\u043a\u0430 \u0445\u0443\u043b\u0456-\u0445\u0443\u043b\u0456"}$j$::jsonb, description = $j${"ru":"\u0413\u0430\u0432\u0430\u0439\u0441\u043a\u0438\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0438\u0437 \u043a\u0443\u0440\u0438\u043d\u043e\u0433\u043e \u0431\u0435\u0434\u0440\u0430 \u0441 \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u043c \u0438 \u043f\u0435\u0440\u0446\u0435\u043c \u0432 \u0433\u043b\u0430\u0437\u0443\u0440\u0438 \u0438\u0437 \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u043e\u0433\u043e \u0441\u043e\u043a\u0430, \u043c\u0451\u0434\u0430, \u0438\u043c\u0431\u0438\u0440\u044f \u0438 \u0440\u0438\u0441\u043e\u0432\u043e\u0433\u043e \u0443\u043a\u0441\u0443\u0441\u0430. \u0413\u043b\u0430\u0437\u0443\u0440\u044c \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u0438\u0437\u0443\u0435\u0442\u0441\u044f \u043d\u0430 \u043e\u0433\u043d\u0435, \u0438 \u043f\u043e\u043b\u0443\u0447\u0430\u0435\u0442\u0441\u044f \u0442\u0440\u043e\u043f\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u043b\u0430\u0434\u043e\u0441\u0442\u044c \u0441 \u0441\u043e\u043b\u0451\u043d\u043e-\u043f\u0440\u044f\u043d\u043e\u0439 \u043d\u043e\u0442\u043a\u043e\u0439 \u2014 \u0438\u0434\u0435\u0430\u043b\u044c\u043d\u043e\u0435 \u0431\u043b\u044e\u0434\u043e \u0434\u043b\u044f \u043b\u0435\u0442\u043d\u0435\u0433\u043e \u0433\u0440\u0438\u043b\u044f.","en":"Hawaiian chicken thigh skewers with pineapple and peppers, glazed with pineapple juice, honey, ginger and rice vinegar. The glaze caramelises over the fire into tropical sweetness with a savoury kick \u2014 made for summer grilling.","ua":"\u0413\u0430\u0432\u0430\u0439\u0441\u044c\u043a\u0456 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0437 \u043a\u0443\u0440\u044f\u0447\u043e\u0433\u043e \u0441\u0442\u0435\u0433\u043d\u0430 \u0437 \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u043c \u0456 \u043f\u0435\u0440\u0446\u0435\u043c \u0443 \u0433\u043b\u0430\u0437\u0443\u0440\u0456 \u0437 \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u043e\u0433\u043e \u0441\u043e\u043a\u0443, \u043c\u0435\u0434\u0443, \u0456\u043c\u0431\u0438\u0440\u0443 \u0439 \u0440\u0438\u0441\u043e\u0432\u043e\u0433\u043e \u043e\u0446\u0442\u0443. \u0413\u043b\u0430\u0437\u0443\u0440 \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u0456\u0437\u0443\u0454\u0442\u044c\u0441\u044f \u043d\u0430 \u0432\u043e\u0433\u043d\u0456, \u0456 \u0432\u0438\u0445\u043e\u0434\u0438\u0442\u044c \u0442\u0440\u043e\u043f\u0456\u0447\u043d\u0430 \u0441\u043e\u043b\u043e\u0434\u043a\u0456\u0441\u0442\u044c \u0456\u0437 \u0441\u043e\u043b\u043e\u043d\u043e-\u043f\u0440\u044f\u043d\u043e\u044e \u043d\u043e\u0442\u043a\u043e\u044e \u2014 \u0456\u0434\u0435\u0430\u043b\u044c\u043d\u0430 \u0441\u0442\u0440\u0430\u0432\u0430 \u0434\u043b\u044f \u043b\u0456\u0442\u043d\u044c\u043e\u0433\u043e \u0433\u0440\u0438\u043b\u044f."}$j$::jsonb, ingredients = $j${"ru":["\u041a\u0443\u0440\u0438\u043d\u043e\u0435 \u0431\u0435\u0434\u0440\u043e \u0431\u0435\u0437 \u043a\u043e\u0441\u0442\u0438 \u2014 800 \u0433","\u0421\u0432\u0435\u0436\u0438\u0439 \u0430\u043d\u0430\u043d\u0430\u0441 \u2014 300 \u0433","\u041a\u0440\u0430\u0441\u043d\u044b\u0439 \u0441\u043b\u0430\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446 \u2014 1 \u0448\u0442","\u0416\u0451\u043b\u0442\u044b\u0439 \u0441\u043b\u0430\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446 \u2014 1 \u0448\u0442","\u041a\u0440\u0430\u0441\u043d\u044b\u0439 \u043b\u0443\u043a \u2014 1 \u0448\u0442","\u0414\u0435\u0440\u0435\u0432\u044f\u043d\u043d\u044b\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u2014 \u043f\u043e \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u0438","\u0421\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441 \u2014 120 \u043c\u043b","\u0410\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u044b\u0439 \u0441\u043e\u043a \u2014 120 \u043c\u043b","\u041a\u0435\u0442\u0447\u0443\u043f \u2014 3 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u044b\u0439 \u0441\u0430\u0445\u0430\u0440 \u2014 3 \u0441\u0442. \u043b.","\u041c\u0451\u0434 \u2014 2 \u0441\u0442. \u043b.","\u0420\u0438\u0441\u043e\u0432\u044b\u0439 \u0443\u043a\u0441\u0443\u0441 \u2014 2 \u0441\u0442. \u043b.","\u0422\u0451\u0440\u0442\u044b\u0439 \u0438\u043c\u0431\u0438\u0440\u044c \u2014 1 \u0441\u0442. \u043b.","\u0427\u0435\u0441\u043d\u043e\u043a \u2014 5 \u0437\u0443\u0431\u0447\u0438\u043a\u043e\u0432","\u041a\u0443\u043d\u0436\u0443\u0442 \u0438 \u0437\u0435\u043b\u0451\u043d\u044b\u0439 \u043b\u0443\u043a \u2014 \u0434\u043b\u044f \u043f\u043e\u0434\u0430\u0447\u0438"],"en":["Boneless chicken thigh \u2014 800 g","Fresh pineapple \u2014 300 g","Red bell pepper \u2014 1 pc","Yellow bell pepper \u2014 1 pc","Red onion \u2014 1 pc","Wooden skewers \u2014 as needed","Soy sauce \u2014 120 ml","Pineapple juice \u2014 120 ml","Ketchup \u2014 3 tbsp","Brown sugar \u2014 3 tbsp","Honey \u2014 2 tbsp","Rice vinegar \u2014 2 tbsp","Grated ginger \u2014 1 tbsp","Garlic \u2014 5 cloves","Sesame seeds and green onion \u2014 to serve"],"ua":["\u041a\u0443\u0440\u044f\u0447\u0435 \u0441\u0442\u0435\u0433\u043d\u043e \u0431\u0435\u0437 \u043a\u0456\u0441\u0442\u043a\u0438 \u2014 800 \u0433","\u0421\u0432\u0456\u0436\u0438\u0439 \u0430\u043d\u0430\u043d\u0430\u0441 \u2014 300 \u0433","\u0427\u0435\u0440\u0432\u043e\u043d\u0438\u0439 \u0441\u043e\u043b\u043e\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 1 \u0448\u0442","\u0416\u043e\u0432\u0442\u0438\u0439 \u0441\u043e\u043b\u043e\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 1 \u0448\u0442","\u0427\u0435\u0440\u0432\u043e\u043d\u0430 \u0446\u0438\u0431\u0443\u043b\u044f \u2014 1 \u0448\u0442","\u0414\u0435\u0440\u0435\u0432'\u044f\u043d\u0456 \u0448\u043f\u0430\u0436\u043a\u0438 \u2014 \u0437\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438","\u0421\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441 \u2014 120 \u043c\u043b","\u0410\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u0438\u0439 \u0441\u0456\u043a \u2014 120 \u043c\u043b","\u041a\u0435\u0442\u0447\u0443\u043f \u2014 3 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u0438\u0439 \u0446\u0443\u043a\u043e\u0440 \u2014 3 \u0441\u0442. \u043b.","\u041c\u0435\u0434 \u2014 2 \u0441\u0442. \u043b.","\u0420\u0438\u0441\u043e\u0432\u0438\u0439 \u043e\u0446\u0435\u0442 \u2014 2 \u0441\u0442. \u043b.","\u0422\u0435\u0440\u0442\u0438\u0439 \u0456\u043c\u0431\u0438\u0440 \u2014 1 \u0441\u0442. \u043b.","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 5 \u0437\u0443\u0431\u0447\u0438\u043a\u0456\u0432","\u041a\u0443\u043d\u0436\u0443\u0442 \u0456 \u0437\u0435\u043b\u0435\u043d\u0430 \u0446\u0438\u0431\u0443\u043b\u044f \u2014 \u0434\u043b\u044f \u043f\u043e\u0434\u0430\u0447\u0456"]}$j$::jsonb, steps = $j${"ru":["\u0421\u043c\u0435\u0448\u0430\u0439\u0442\u0435 \u0441\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441, \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u044b\u0439 \u0441\u043e\u043a, \u043a\u0435\u0442\u0447\u0443\u043f, \u0441\u0430\u0445\u0430\u0440, \u043c\u0451\u0434, \u0443\u043a\u0441\u0443\u0441, \u0438\u043c\u0431\u0438\u0440\u044c \u0438 \u0434\u0430\u0432\u043b\u0435\u043d\u044b\u0439 \u0447\u0435\u0441\u043d\u043e\u043a. \u041e\u0442\u043b\u0435\u0439\u0442\u0435 \u0442\u0440\u0435\u0442\u044c \u0441\u043e\u0443\u0441\u0430 \u0434\u043b\u044f \u0441\u043c\u0430\u0437\u044b\u0432\u0430\u043d\u0438\u044f.","\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443, \u0430\u043d\u0430\u043d\u0430\u0441, \u043f\u0435\u0440\u0435\u0446 \u0438 \u043b\u0443\u043a \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u043c\u0438 \u043a\u0443\u0431\u0438\u043a\u0430\u043c\u0438 \u043f\u043e 3 \u0441\u043c.","\u0417\u0430\u043b\u0435\u0439\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443 \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u043c \u0441\u043e\u0443\u0441\u043e\u043c \u0438 \u043c\u0430\u0440\u0438\u043d\u0443\u0439\u0442\u0435 4\u20138 \u0447\u0430\u0441\u043e\u0432 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0435. \u0428\u043f\u0430\u0436\u043a\u0438 \u0437\u0430\u043c\u043e\u0447\u0438\u0442\u0435 \u0432 \u0432\u043e\u0434\u0435 \u043d\u0430 30 \u043c\u0438\u043d\u0443\u0442.","\u041d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u043a\u0443\u0440\u0438\u0446\u0443, \u0430\u043d\u0430\u043d\u0430\u0441 \u0438 \u043e\u0432\u043e\u0449\u0438, \u0447\u0435\u0440\u0435\u0434\u0443\u044f \u0438\u0445.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430 \u0441\u0440\u0435\u0434\u043d\u0435-\u0441\u0438\u043b\u044c\u043d\u043e\u043c \u043e\u0433\u043d\u0435 12\u201315 \u043c\u0438\u043d\u0443\u0442, \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f \u043a\u0430\u0436\u0434\u044b\u0435 3\u20134 \u043c\u0438\u043d\u0443\u0442\u044b.","\u0412 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u043c\u0438\u043d\u0443\u0442\u044b \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0440\u0430\u0437 \u0441\u043c\u0430\u0436\u044c\u0442\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u043e\u0442\u043b\u043e\u0436\u0435\u043d\u043d\u044b\u043c \u0441\u043e\u0443\u0441\u043e\u043c, \u0447\u0442\u043e\u0431\u044b \u0433\u043b\u0430\u0437\u0443\u0440\u044c \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u0438\u0437\u043e\u0432\u0430\u043b\u0430\u0441\u044c.","\u0414\u0430\u0439\u0442\u0435 \u043c\u044f\u0441\u0443 \u043e\u0442\u0434\u043e\u0445\u043d\u0443\u0442\u044c 2 \u043c\u0438\u043d\u0443\u0442\u044b.","\u041f\u043e\u0441\u044b\u043f\u044c\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0438 \u0437\u0435\u043b\u0451\u043d\u044b\u043c \u043b\u0443\u043a\u043e\u043c, \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0440\u0438\u0441\u043e\u043c, \u0441\u0430\u043b\u0430\u0442\u043e\u043c \u0438 \u0434\u043e\u043b\u044c\u043a\u0430\u043c\u0438 \u043b\u0430\u0439\u043c\u0430."],"en":["Whisk the soy sauce, pineapple juice, ketchup, sugar, honey, vinegar, ginger and crushed garlic. Set a third of the sauce aside for basting.","Cut the chicken, pineapple, peppers and onion into even 3 cm cubes.","Pour the rest of the sauce over the chicken and marinate in the fridge for 4\u20138 hours. Soak the skewers in water for 30 minutes.","Thread the chicken, pineapple and vegetables onto the skewers, alternating them.","Grill over medium-high heat for 12\u201315 minutes in total, turning every 3\u20134 minutes.","Brush with the reserved sauce several times in the last minutes so the glaze caramelises.","Let the meat rest for 2 minutes.","Sprinkle with sesame seeds and green onion and serve with rice, lettuce and lime wedges."],"ua":["\u0417\u043c\u0456\u0448\u0430\u0439\u0442\u0435 \u0441\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441, \u0430\u043d\u0430\u043d\u0430\u0441\u043e\u0432\u0438\u0439 \u0441\u0456\u043a, \u043a\u0435\u0442\u0447\u0443\u043f, \u0446\u0443\u043a\u043e\u0440, \u043c\u0435\u0434, \u043e\u0446\u0435\u0442, \u0456\u043c\u0431\u0438\u0440 \u0456 \u0447\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u0447\u0430\u0441\u043d\u0438\u043a. \u0412\u0456\u0434\u043b\u0438\u0439\u0442\u0435 \u0442\u0440\u0435\u0442\u0438\u043d\u0443 \u0441\u043e\u0443\u0441\u0443 \u0434\u043b\u044f \u0437\u043c\u0430\u0449\u0443\u0432\u0430\u043d\u043d\u044f.","\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u043a\u0443\u0440\u043a\u0443, \u0430\u043d\u0430\u043d\u0430\u0441, \u043f\u0435\u0440\u0435\u0446\u044c \u0456 \u0446\u0438\u0431\u0443\u043b\u044e \u043e\u0434\u043d\u0430\u043a\u043e\u0432\u0438\u043c\u0438 \u043a\u0443\u0431\u0438\u043a\u0430\u043c\u0438 \u043f\u043e 3 \u0441\u043c.","\u0417\u0430\u043b\u0438\u0439\u0442\u0435 \u043a\u0443\u0440\u043a\u0443 \u0440\u0435\u0448\u0442\u043e\u044e \u0441\u043e\u0443\u0441\u0443 \u0439 \u043c\u0430\u0440\u0438\u043d\u0443\u0439\u0442\u0435 4\u20138 \u0433\u043e\u0434\u0438\u043d \u0443 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0443. \u0428\u043f\u0430\u0436\u043a\u0438 \u0437\u0430\u043c\u043e\u0447\u0456\u0442\u044c \u0443 \u0432\u043e\u0434\u0456 \u043d\u0430 30 \u0445\u0432\u0438\u043b\u0438\u043d.","\u041d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u043a\u0443\u0440\u043a\u0443, \u0430\u043d\u0430\u043d\u0430\u0441 \u0456 \u043e\u0432\u043e\u0447\u0456, \u0447\u0435\u0440\u0433\u0443\u044e\u0447\u0438 \u0457\u0445.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430 \u0441\u0435\u0440\u0435\u0434\u043d\u044c\u043e-\u0441\u0438\u043b\u044c\u043d\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 12\u201315 \u0445\u0432\u0438\u043b\u0438\u043d, \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u0442\u0430\u044e\u0447\u0438 \u043a\u043e\u0436\u043d\u0456 3\u20134 \u0445\u0432\u0438\u043b\u0438\u043d\u0438.","\u0412 \u043e\u0441\u0442\u0430\u043d\u043d\u0456 \u0445\u0432\u0438\u043b\u0438\u043d\u0438 \u043a\u0456\u043b\u044c\u043a\u0430 \u0440\u0430\u0437\u0456\u0432 \u0437\u043c\u0430\u0441\u0442\u0456\u0442\u044c \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0432\u0456\u0434\u043a\u043b\u0430\u0434\u0435\u043d\u0438\u043c \u0441\u043e\u0443\u0441\u043e\u043c, \u0449\u043e\u0431 \u0433\u043b\u0430\u0437\u0443\u0440 \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u0456\u0437\u0443\u0432\u0430\u043b\u0430\u0441\u044f.","\u0414\u0430\u0439\u0442\u0435 \u043c'\u044f\u0441\u0443 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u0442\u0438 2 \u0445\u0432\u0438\u043b\u0438\u043d\u0438.","\u041f\u043e\u0441\u0438\u043f\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0456 \u0437\u0435\u043b\u0435\u043d\u043e\u044e \u0446\u0438\u0431\u0443\u043b\u0435\u044e, \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0437 \u0440\u0438\u0441\u043e\u043c, \u0441\u0430\u043b\u0430\u0442\u043e\u043c \u0456 \u0447\u0430\u0441\u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u043b\u0430\u0439\u043c\u0430."]}$j$::jsonb, tags = $j${"ru":["\u0433\u0430\u0432\u0430\u0439\u0441\u043a\u0430\u044f \u043a\u0443\u0445\u043d\u044f","\u043a\u0443\u0440\u0438\u0446\u0430","\u0430\u043d\u0430\u043d\u0430\u0441","\u0433\u0440\u0438\u043b\u044c","\u044d\u043a\u0437\u043e\u0442\u0438\u043a\u0430"],"en":["hawaiian","chicken","pineapple","grilled","tropical"],"ua":["\u0433\u0430\u0432\u0430\u0439\u0441\u044c\u043a\u0430 \u043a\u0443\u0445\u043d\u044f","\u043a\u0443\u0440\u043a\u0430","\u0430\u043d\u0430\u043d\u0430\u0441","\u0433\u0440\u0438\u043b\u044c","\u0435\u043a\u0437\u043e\u0442\u0438\u043a\u0430"]}$j$::jsonb where slug = 'huli-huli-chicken' and not (title ? 'ua');
update recipes set title = $j${"ru":"\u0421\u0430\u0442\u0430\u0439 \u2014 \u0438\u043d\u0434\u043e\u043d\u0435\u0437\u0438\u0439\u0441\u043a\u0438\u0435 \u043a\u0443\u0440\u0438\u043d\u044b\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0441 \u0430\u0440\u0430\u0445\u0438\u0441\u043e\u0432\u044b\u043c \u0441\u043e\u0443\u0441\u043e\u043c","en":"Satay \u2014 Indonesian Peanut Chicken Skewers","ua":"\u0421\u0430\u0442\u0430\u0439 \u2014 \u0456\u043d\u0434\u043e\u043d\u0435\u0437\u0456\u0439\u0441\u044c\u043a\u0456 \u043a\u0443\u0440\u044f\u0447\u0456 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0437 \u0430\u0440\u0430\u0445\u0456\u0441\u043e\u0432\u0438\u043c \u0441\u043e\u0443\u0441\u043e\u043c"}$j$::jsonb, description = $j${"ru":"\u0421\u043e\u0447\u043d\u044b\u0435 \u043a\u0443\u0440\u0438\u043d\u044b\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0435 \u0441 \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u044b\u043c \u043c\u043e\u043b\u043e\u043a\u043e\u043c, \u043a\u0443\u0440\u043a\u0443\u043c\u043e\u0439 \u0438 \u043a\u043e\u0440\u0438\u0430\u043d\u0434\u0440\u043e\u043c, \u043e\u0431\u0436\u0430\u0440\u0435\u043d\u043d\u044b\u0435 \u0434\u043e \u0437\u043e\u043b\u043e\u0442\u0438\u0441\u0442\u043e\u0433\u043e \u0446\u0432\u0435\u0442\u0430. \u041a \u043d\u0438\u043c \u2014 \u0441\u043b\u0438\u0432\u043e\u0447\u043d\u044b\u0439 \u0430\u0440\u0430\u0445\u0438\u0441\u043e\u0432\u043e-\u043a\u043e\u043a\u043e\u0441\u043e\u0432\u044b\u0439 \u0441\u043e\u0443\u0441 \u0441 \u043b\u0430\u0439\u043c\u043e\u043c \u0438 \u043b\u0451\u0433\u043a\u043e\u0439 \u043e\u0441\u0442\u0440\u043e\u0442\u043e\u0439 \u0441\u0432\u0435\u0436\u0435\u0433\u043e \u0447\u0438\u043b\u0438. \u041b\u044e\u0431\u0438\u043c\u0430\u044f \u0443\u043b\u0438\u0447\u043d\u0430\u044f \u0435\u0434\u0430 \u042e\u0433\u043e-\u0412\u043e\u0441\u0442\u043e\u0447\u043d\u043e\u0439 \u0410\u0437\u0438\u0438, \u043a\u043e\u0442\u043e\u0440\u0443\u044e \u043b\u0435\u0433\u043a\u043e \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u044c \u0434\u043e\u043c\u0430.","en":"Juicy chicken skewers marinated in coconut milk, turmeric and coriander, grilled until golden. They come with a creamy peanut and coconut sauce brightened with lime and a gentle heat of fresh chili. Southeast Asia's favourite street food, easy to make at home.","ua":"\u0421\u043e\u043a\u043e\u0432\u0438\u0442\u0456 \u043a\u0443\u0440\u044f\u0447\u0456 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0456 \u0437 \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u0438\u043c \u043c\u043e\u043b\u043e\u043a\u043e\u043c, \u043a\u0443\u0440\u043a\u0443\u043c\u043e\u044e \u0439 \u043a\u043e\u0440\u0456\u0430\u043d\u0434\u0440\u043e\u043c, \u043e\u0431\u0441\u043c\u0430\u0436\u0435\u043d\u0456 \u0434\u043e \u0437\u043e\u043b\u043e\u0442\u0438\u0441\u0442\u043e\u0433\u043e \u043a\u043e\u043b\u044c\u043e\u0440\u0443. \u0414\u043e \u043d\u0438\u0445 \u2014 \u0432\u0435\u0440\u0448\u043a\u043e\u0432\u0438\u0439 \u0430\u0440\u0430\u0445\u0456\u0441\u043e\u0432\u043e-\u043a\u043e\u043a\u043e\u0441\u043e\u0432\u0438\u0439 \u0441\u043e\u0443\u0441 \u0456\u0437 \u043b\u0430\u0439\u043c\u043e\u043c \u0456 \u043b\u0435\u0433\u043a\u043e\u044e \u0433\u043e\u0441\u0442\u0440\u043e\u0442\u043e\u044e \u0441\u0432\u0456\u0436\u043e\u0433\u043e \u0447\u0438\u043b\u0456. \u0423\u043b\u044e\u0431\u043b\u0435\u043d\u0430 \u0432\u0443\u043b\u0438\u0447\u043d\u0430 \u0457\u0436\u0430 \u041f\u0456\u0432\u0434\u0435\u043d\u043d\u043e-\u0421\u0445\u0456\u0434\u043d\u043e\u0457 \u0410\u0437\u0456\u0457, \u044f\u043a\u0443 \u043b\u0435\u0433\u043a\u043e \u043f\u043e\u0432\u0442\u043e\u0440\u0438\u0442\u0438 \u0432\u0434\u043e\u043c\u0430."}$j$::jsonb, ingredients = $j${"ru":["\u041a\u0443\u0440\u0438\u043d\u043e\u0435 \u0431\u0435\u0434\u0440\u043e \u0438\u043b\u0438 \u0433\u0440\u0443\u0434\u043a\u0430 \u2014 700 \u0433","\u041a\u043e\u043a\u043e\u0441\u043e\u0432\u043e\u0435 \u043c\u043e\u043b\u043e\u043a\u043e \u2014 250 \u043c\u043b (\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434, \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0432 \u0441\u043e\u0443\u0441)","\u0421\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441 \u2014 2 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u044b\u0439 \u0441\u0430\u0445\u0430\u0440 \u2014 1 \u0441\u0442. \u043b.","\u0427\u0435\u0441\u043d\u043e\u043a \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0430","\u0422\u0451\u0440\u0442\u044b\u0439 \u0438\u043c\u0431\u0438\u0440\u044c \u2014 1 \u0441\u0442. \u043b.","\u041a\u0443\u0440\u043a\u0443\u043c\u0430 \u2014 1 \u0447. \u043b.","\u041c\u043e\u043b\u043e\u0442\u044b\u0439 \u043a\u043e\u0440\u0438\u0430\u043d\u0434\u0440 \u2014 1 \u0447. \u043b.","\u0417\u0438\u0440\u0430 \u2014 \u00bd \u0447. \u043b.","\u0410\u0440\u0430\u0445\u0438\u0441\u043e\u0432\u0430\u044f \u043f\u0430\u0441\u0442\u0430 \u2014 4 \u0441\u0442. \u043b.","\u0421\u0432\u0435\u0436\u0438\u0439 \u043a\u0440\u0430\u0441\u043d\u044b\u0439 \u0447\u0438\u043b\u0438 \u2014 1 \u0448\u0442","\u0421\u043e\u043a \u043b\u0430\u0439\u043c\u0430 \u2014 2 \u0441\u0442. \u043b.","\u0421\u043e\u043b\u044c \u2014 \u00bd \u0447. \u043b."],"en":["Chicken thigh or breast \u2014 700 g","Coconut milk \u2014 250 ml (half for the marinade, half for the sauce)","Soy sauce \u2014 2 tbsp","Brown sugar \u2014 1 tbsp","Garlic cloves \u2014 3 pieces","Grated ginger \u2014 1 tbsp","Turmeric \u2014 1 tsp","Ground coriander \u2014 1 tsp","Cumin \u2014 \u00bd tsp","Peanut butter \u2014 4 tbsp","Fresh red chili \u2014 1 pc","Lime juice \u2014 2 tbsp","Salt \u2014 \u00bd tsp"],"ua":["\u041a\u0443\u0440\u044f\u0447\u0435 \u0441\u0442\u0435\u0433\u043d\u043e \u0430\u0431\u043e \u0433\u0440\u0443\u0434\u043a\u0430 \u2014 700 \u0433","\u041a\u043e\u043a\u043e\u0441\u043e\u0432\u0435 \u043c\u043e\u043b\u043e\u043a\u043e \u2014 250 \u043c\u043b (\u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0432 \u043c\u0430\u0440\u0438\u043d\u0430\u0434, \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u0432 \u0441\u043e\u0443\u0441)","\u0421\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441 \u2014 2 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u0438\u0439 \u0446\u0443\u043a\u043e\u0440 \u2014 1 \u0441\u0442. \u043b.","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u0422\u0435\u0440\u0442\u0438\u0439 \u0456\u043c\u0431\u0438\u0440 \u2014 1 \u0441\u0442. \u043b.","\u041a\u0443\u0440\u043a\u0443\u043c\u0430 \u2014 1 \u0447. \u043b.","\u041c\u0435\u043b\u0435\u043d\u0438\u0439 \u043a\u043e\u0440\u0456\u0430\u043d\u0434\u0440 \u2014 1 \u0447. \u043b.","\u0417\u0456\u0440\u0430 \u2014 \u00bd \u0447. \u043b.","\u0410\u0440\u0430\u0445\u0456\u0441\u043e\u0432\u0430 \u043f\u0430\u0441\u0442\u0430 \u2014 4 \u0441\u0442. \u043b.","\u0421\u0432\u0456\u0436\u0438\u0439 \u0447\u0435\u0440\u0432\u043e\u043d\u0438\u0439 \u0447\u0438\u043b\u0456 \u2014 1 \u0448\u0442","\u0421\u0456\u043a \u043b\u0430\u0439\u043c\u0430 \u2014 2 \u0441\u0442. \u043b.","\u0421\u0456\u043b\u044c \u2014 \u00bd \u0447. \u043b."]}$j$::jsonb, steps = $j${"ru":["\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443 \u043a\u0443\u0441\u043e\u0447\u043a\u0430\u043c\u0438 \u043f\u043e 3\u20134 \u0441\u043c.","\u0421\u043c\u0435\u0448\u0430\u0439\u0442\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443 \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u043e\u0433\u043e \u043c\u043e\u043b\u043e\u043a\u0430 \u0441 \u0441\u043e\u0435\u0432\u044b\u043c \u0441\u043e\u0443\u0441\u043e\u043c, \u0441\u0430\u0445\u0430\u0440\u043e\u043c, \u0434\u0430\u0432\u043b\u0435\u043d\u044b\u043c \u0447\u0435\u0441\u043d\u043e\u043a\u043e\u043c, \u0438\u043c\u0431\u0438\u0440\u0451\u043c, \u043a\u0443\u0440\u043a\u0443\u043c\u043e\u0439, \u043a\u043e\u0440\u0438\u0430\u043d\u0434\u0440\u043e\u043c, \u0437\u0438\u0440\u043e\u0439 \u0438 \u0441\u043e\u043b\u044c\u044e.","\u0417\u0430\u043b\u0435\u0439\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c \u0438 \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0435 \u043d\u0430 2\u20134 \u0447\u0430\u0441\u0430. \u0414\u0435\u0440\u0435\u0432\u044f\u043d\u043d\u044b\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u0437\u0430\u043c\u043e\u0447\u0438\u0442\u0435 \u0432 \u0432\u043e\u0434\u0435 \u043d\u0430 30 \u043c\u0438\u043d\u0443\u0442.","\u041d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043a\u0443\u0441\u043e\u0447\u043a\u0438 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u043f\u043b\u043e\u0442\u043d\u043e \u0434\u0440\u0443\u0433 \u043a \u0434\u0440\u0443\u0433\u0443.","\u0414\u043b\u044f \u0441\u043e\u0443\u0441\u0430 \u043f\u0440\u043e\u0433\u0440\u0435\u0439\u0442\u0435 \u043e\u0441\u0442\u0430\u0432\u0448\u0435\u0435\u0441\u044f \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u043e\u0435 \u043c\u043e\u043b\u043e\u043a\u043e \u0441 \u0430\u0440\u0430\u0445\u0438\u0441\u043e\u0432\u043e\u0439 \u043f\u0430\u0441\u0442\u043e\u0439, \u043c\u0435\u043b\u043a\u043e \u043d\u0430\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u043c \u0447\u0438\u043b\u0438 \u0438 \u0441\u043e\u043a\u043e\u043c \u043b\u0430\u0439\u043c\u0430, \u043f\u043e\u043c\u0435\u0448\u0438\u0432\u0430\u044f \u0434\u043e \u043a\u0440\u0435\u043c\u043e\u0432\u043e\u0439 \u0433\u0443\u0441\u0442\u043e\u0442\u044b.","\u0416\u0430\u0440\u044c\u0442\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u043d\u0430 \u0443\u0433\u043b\u044f\u0445 \u0438\u043b\u0438 \u0440\u0430\u0441\u043a\u0430\u043b\u0451\u043d\u043d\u043e\u043c \u0433\u0440\u0438\u043b\u0435 8\u201310 \u043c\u0438\u043d\u0443\u0442, \u0432\u0440\u0435\u043c\u044f \u043e\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f.","\u0412 \u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0438\u0435 \u043c\u0438\u043d\u0443\u0442\u044b \u0441\u043c\u0430\u0436\u044c\u0442\u0435 \u0438\u0445 \u043b\u043e\u0436\u043a\u043e\u0439 \u0441\u043e\u0443\u0441\u0430.","\u041f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0430\u0440\u0430\u0445\u0438\u0441\u043e\u0432\u044b\u043c \u0441\u043e\u0443\u0441\u043e\u043c, \u0434\u043e\u043b\u044c\u043a\u0430\u043c\u0438 \u043b\u0430\u0439\u043c\u0430 \u0438 \u0441\u0432\u0435\u0436\u0438\u043c\u0438 \u043e\u0432\u043e\u0449\u0430\u043c\u0438. \u0411\u0435\u0434\u0440\u043e \u043d\u0430 \u0433\u0440\u0438\u043b\u0435 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f \u0441\u043e\u0447\u043d\u0435\u0435 \u0433\u0440\u0443\u0434\u043a\u0438."],"en":["Cut the chicken into 3\u20134 cm pieces.","Mix half the coconut milk with the soy sauce, sugar, crushed garlic, ginger, turmeric, coriander, cumin and salt.","Pour the marinade over the chicken and leave in the fridge for 2\u20134 hours. Soak wooden skewers in water for 30 minutes.","Thread the pieces snugly onto the skewers.","For the sauce, warm the remaining coconut milk with the peanut butter, finely chopped chili and lime juice, stirring until creamy.","Grill the skewers over coals or on a hot grill for 8\u201310 minutes, turning occasionally.","Brush them with a spoonful of the sauce in the last minutes.","Serve with the peanut sauce, lime wedges and fresh vegetables. Thigh meat stays juicier on the grill than breast."],"ua":["\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u043a\u0443\u0440\u043a\u0443 \u0448\u043c\u0430\u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u043f\u043e 3\u20134 \u0441\u043c.","\u0417\u043c\u0456\u0448\u0430\u0439\u0442\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443 \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u043e\u0433\u043e \u043c\u043e\u043b\u043e\u043a\u0430 \u0456\u0437 \u0441\u043e\u0454\u0432\u0438\u043c \u0441\u043e\u0443\u0441\u043e\u043c, \u0446\u0443\u043a\u0440\u043e\u043c, \u0447\u0430\u0432\u043b\u0435\u043d\u0438\u043c \u0447\u0430\u0441\u043d\u0438\u043a\u043e\u043c, \u0456\u043c\u0431\u0438\u0440\u043e\u043c, \u043a\u0443\u0440\u043a\u0443\u043c\u043e\u044e, \u043a\u043e\u0440\u0456\u0430\u043d\u0434\u0440\u043e\u043c, \u0437\u0456\u0440\u043e\u044e \u0439 \u0441\u0456\u043b\u043b\u044e.","\u0417\u0430\u043b\u0438\u0439\u0442\u0435 \u043a\u0443\u0440\u043a\u0443 \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c \u0456 \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0443 \u043d\u0430 2\u20134 \u0433\u043e\u0434\u0438\u043d\u0438. \u0414\u0435\u0440\u0435\u0432'\u044f\u043d\u0456 \u0448\u043f\u0430\u0436\u043a\u0438 \u0437\u0430\u043c\u043e\u0447\u0456\u0442\u044c \u0443 \u0432\u043e\u0434\u0456 \u043d\u0430 30 \u0445\u0432\u0438\u043b\u0438\u043d.","\u041d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u0448\u043c\u0430\u0442\u043e\u0447\u043a\u0438 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438 \u0449\u0456\u043b\u044c\u043d\u043e \u043e\u0434\u0438\u043d \u0434\u043e \u043e\u0434\u043d\u043e\u0433\u043e.","\u0414\u043b\u044f \u0441\u043e\u0443\u0441\u0443 \u043f\u0440\u043e\u0433\u0440\u0456\u0439\u0442\u0435 \u0440\u0435\u0448\u0442\u0443 \u043a\u043e\u043a\u043e\u0441\u043e\u0432\u043e\u0433\u043e \u043c\u043e\u043b\u043e\u043a\u0430 \u0437 \u0430\u0440\u0430\u0445\u0456\u0441\u043e\u0432\u043e\u044e \u043f\u0430\u0441\u0442\u043e\u044e, \u0434\u0440\u0456\u0431\u043d\u043e \u043d\u0430\u0440\u0456\u0437\u0430\u043d\u0438\u043c \u0447\u0438\u043b\u0456 \u0439 \u0441\u043e\u043a\u043e\u043c \u043b\u0430\u0439\u043c\u0430, \u043f\u043e\u043c\u0456\u0448\u0443\u044e\u0447\u0438 \u0434\u043e \u0432\u0435\u0440\u0448\u043a\u043e\u0432\u043e\u0457 \u0433\u0443\u0441\u0442\u043e\u0442\u0438.","\u0421\u043c\u0430\u0436\u0442\u0435 \u0448\