\u00bd tsp"],"ua":["\u0411\u0430\u0440\u0430\u043d\u044f\u0447\u0430 \u043b\u043e\u043f\u0430\u0442\u043a\u0430 \u2014 800 \u0433","\u041a\u0443\u0440\u0430\u0433\u0430 \u2014 150 \u0433","\u0427\u0435\u0440\u0432\u043e\u043d\u0430 \u0446\u0438\u0431\u0443\u043b\u044f \u2014 2 \u0448\u0442","\u0427\u0435\u0440\u0432\u043e\u043d\u0438\u0439 \u0441\u043e\u043b\u043e\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 1 \u0448\u0442","\u0416\u043e\u0432\u0442\u0438\u0439 \u0441\u043e\u043b\u043e\u0434\u043a\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 1 \u0448\u0442","\u0414\u0435\u0440\u0435\u0432'\u044f\u043d\u0456 \u0430\u0431\u043e \u043c\u0435\u0442\u0430\u043b\u0435\u0432\u0456 \u0448\u0430\u043c\u043f\u0443\u0440\u0438 \u2014 \u0437\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0438","\u0410\u0431\u0440\u0438\u043a\u043e\u0441\u043e\u0432\u0438\u0439 \u0434\u0436\u0435\u043c \u2014 2 \u0441\u0442. \u043b.","\u042f\u0431\u043b\u0443\u0447\u043d\u0438\u0439 \u043e\u0446\u0435\u0442 \u2014 3 \u0441\u0442. \u043b.","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u0438\u0439 \u0446\u0443\u043a\u043e\u0440 \u2014 2 \u0441\u0442. \u043b.","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 3 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u041a\u0430\u0440\u0456 \u2014 2 \u0447. \u043b.","\u041c\u0435\u043b\u0435\u043d\u0438\u0439 \u043a\u043e\u0440\u0456\u0430\u043d\u0434\u0440 \u2014 1 \u0447. \u043b.","\u0417\u0456\u0440\u0430 \u2014 1 \u0447. \u043b.","\u041f\u0430\u043f\u0440\u0438\u043a\u0430 \u2014 1 \u0447. \u043b.","\u0421\u0456\u043b\u044c \u2014 \u00bd \u0447. \u043b.","\u0427\u043e\u0440\u043d\u0438\u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u2014 \u00bd \u0447. \u043b."]}$j$::jsonb, steps = $j${"ru":["\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0443 \u043a\u0440\u0443\u043f\u043d\u044b\u043c\u0438 \u043a\u0443\u0431\u0438\u043a\u0430\u043c\u0438 \u043f\u043e 3\u20134 \u0441\u043c.","\u0421\u043c\u0435\u0448\u0430\u0439\u0442\u0435 \u0434\u0436\u0435\u043c, \u0443\u043a\u0441\u0443\u0441, \u0441\u0430\u0445\u0430\u0440, \u0434\u0430\u0432\u043b\u0435\u043d\u044b\u0439 \u0447\u0435\u0441\u043d\u043e\u043a \u0438 \u0432\u0441\u0435 \u0441\u043f\u0435\u0446\u0438\u0438.","\u0417\u0430\u043b\u0435\u0439\u0442\u0435 \u043c\u044f\u0441\u043e \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c \u0438 \u043e\u0441\u0442\u0430\u0432\u044c\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0435 \u043d\u0430 6\u20138 \u0447\u0430\u0441\u043e\u0432 \u0438\u043b\u0438 \u043d\u0430 \u043d\u043e\u0447\u044c.","\u041a\u0443\u0440\u0430\u0433\u0443 \u0437\u0430\u043b\u0435\u0439\u0442\u0435 \u0433\u043e\u0440\u044f\u0447\u0435\u0439 \u0432\u043e\u0434\u043e\u0439 \u043d\u0430 15 \u043c\u0438\u043d\u0443\u0442, \u0447\u0442\u043e\u0431\u044b \u043e\u043d\u0430 \u043d\u0430\u0431\u0443\u0445\u043b\u0430. \u0414\u0435\u0440\u0435\u0432\u044f\u043d\u043d\u044b\u0435 \u0448\u0430\u043c\u043f\u0443\u0440\u044b \u0437\u0430\u043c\u043e\u0447\u0438\u0442\u0435 \u0432 \u0432\u043e\u0434\u0435.","\u041b\u0443\u043a \u0438 \u043f\u0435\u0440\u0435\u0446 \u043d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u043a\u0440\u0443\u043f\u043d\u044b\u043c\u0438 \u043a\u0443\u0441\u043a\u0430\u043c\u0438 \u0438 \u043d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u044b \u0432\u043f\u0435\u0440\u0435\u043c\u0435\u0448\u043a\u0443 \u0441 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u043e\u0439 \u0438 \u043a\u0443\u0440\u0430\u0433\u043e\u0439.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430\u0434 \u0433\u043e\u0440\u044f\u0447\u0438\u043c\u0438 \u0443\u0433\u043b\u044f\u043c\u0438 12\u201315 \u043c\u0438\u043d\u0443\u0442, \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f.","\u0412\u043e \u0432\u0440\u0435\u043c\u044f \u0436\u0430\u0440\u043a\u0438 \u0441\u043c\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0448\u0430\u0448\u043b\u044b\u043a \u043e\u0441\u0442\u0430\u0432\u0448\u0438\u043c\u0441\u044f \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c.","\u0414\u0430\u0439\u0442\u0435 \u043c\u044f\u0441\u0443 \u043e\u0442\u0434\u043e\u0445\u043d\u0443\u0442\u044c 5 \u043c\u0438\u043d\u0443\u0442 \u0438 \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0441 \u0437\u0435\u043b\u0435\u043d\u044c\u044e, \u043a\u0443\u043a\u0443\u0440\u0443\u0437\u043e\u0439 \u043d\u0430 \u0433\u0440\u0438\u043b\u0435 \u0438\u043b\u0438 \u0440\u0438\u0441\u043e\u043c."],"en":["Cut the lamb into large 3\u20134 cm cubes.","Whisk the jam, vinegar, sugar, crushed garlic and all the spices.","Pour the marinade over the meat and leave in the fridge for 6\u20138 hours or overnight.","Cover the dried apricots with hot water for 15 minutes to plump them. Soak wooden skewers in water.","Cut the onion and peppers into large pieces and thread them onto the skewers with the lamb and apricots.","Grill over hot charcoal for 12\u201315 minutes, turning.","Baste with the remaining marinade while grilling.","Let the meat rest for 5 minutes and serve with fresh herbs, grilled corn or rice."],"ua":["\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u0443 \u0432\u0435\u043b\u0438\u043a\u0438\u043c\u0438 \u043a\u0443\u0431\u0438\u043a\u0430\u043c\u0438 \u043f\u043e 3\u20134 \u0441\u043c.","\u0417\u043c\u0456\u0448\u0430\u0439\u0442\u0435 \u0434\u0436\u0435\u043c, \u043e\u0446\u0435\u0442, \u0446\u0443\u043a\u043e\u0440, \u0447\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u0447\u0430\u0441\u043d\u0438\u043a \u0456 \u0432\u0441\u0456 \u0441\u043f\u0435\u0446\u0456\u0457.","\u0417\u0430\u043b\u0438\u0439\u0442\u0435 \u043c'\u044f\u0441\u043e \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u043e\u043c \u0456 \u0437\u0430\u043b\u0438\u0448\u0442\u0435 \u0432 \u0445\u043e\u043b\u043e\u0434\u0438\u043b\u044c\u043d\u0438\u043a\u0443 \u043d\u0430 6\u20138 \u0433\u043e\u0434\u0438\u043d \u0430\u0431\u043e \u043d\u0430 \u043d\u0456\u0447.","\u041a\u0443\u0440\u0430\u0433\u0443 \u0437\u0430\u043b\u0438\u0439\u0442\u0435 \u0433\u0430\u0440\u044f\u0447\u043e\u044e \u0432\u043e\u0434\u043e\u044e \u043d\u0430 15 \u0445\u0432\u0438\u043b\u0438\u043d, \u0449\u043e\u0431 \u0432\u043e\u043d\u0430 \u043d\u0430\u0431\u0443\u0445\u043b\u0430. \u0414\u0435\u0440\u0435\u0432'\u044f\u043d\u0456 \u0448\u0430\u043c\u043f\u0443\u0440\u0438 \u0437\u0430\u043c\u043e\u0447\u0456\u0442\u044c \u0443 \u0432\u043e\u0434\u0456.","\u0426\u0438\u0431\u0443\u043b\u044e \u0439 \u043f\u0435\u0440\u0435\u0446\u044c \u043d\u0430\u0440\u0456\u0436\u0442\u0435 \u0432\u0435\u043b\u0438\u043a\u0438\u043c\u0438 \u0448\u043c\u0430\u0442\u043a\u0430\u043c\u0438 \u0439 \u043d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u043d\u0430 \u0448\u0430\u043c\u043f\u0443\u0440\u0438 \u0432\u043f\u0435\u0440\u0435\u043c\u0456\u0436 \u0437 \u0431\u0430\u0440\u0430\u043d\u0438\u043d\u043e\u044e \u0439 \u043a\u0443\u0440\u0430\u0433\u043e\u044e.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430\u0434 \u0433\u0430\u0440\u044f\u0447\u0438\u043c \u0432\u0443\u0433\u0456\u043b\u043b\u044f\u043c 12\u201315 \u0445\u0432\u0438\u043b\u0438\u043d, \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u0442\u0430\u044e\u0447\u0438.","\u041f\u0456\u0434 \u0447\u0430\u0441 \u0441\u043c\u0430\u0436\u0435\u043d\u043d\u044f \u0437\u043c\u0430\u0449\u0443\u0439\u0442\u0435 \u0448\u0430\u0448\u043b\u0438\u043a \u0440\u0435\u0448\u0442\u043e\u044e \u043c\u0430\u0440\u0438\u043d\u0430\u0434\u0443.","\u0414\u0430\u0439\u0442\u0435 \u043c'\u044f\u0441\u0443 \u0432\u0456\u0434\u043f\u043e\u0447\u0438\u0442\u0438 5 \u0445\u0432\u0438\u043b\u0438\u043d \u0456 \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0456\u0437 \u0437\u0435\u043b\u0435\u043d\u043d\u044e, \u043a\u0443\u043a\u0443\u0440\u0443\u0434\u0437\u043e\u044e \u043d\u0430 \u0433\u0440\u0438\u043b\u0456 \u0430\u0431\u043e \u0