update recipes set title = $j${"ru":"\u042f\u043a\u0438\u0442\u043e\u0440\u0438","en":"Yakitori","ua":"\u042f\u043a\u0456\u0442\u043e\u0440\u0456"}$j$::jsonb, description = $j${"ru":"\u042f\u043f\u043e\u043d\u0441\u043a\u0438\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0438\u0437 \u043a\u0443\u0440\u0438\u043d\u043e\u0433\u043e \u0431\u0435\u0434\u0440\u0430 \u0441 \u0437\u0435\u043b\u0451\u043d\u044b\u043c \u043b\u0443\u043a\u043e\u043c \u0432 \u0431\u043b\u0435\u0441\u0442\u044f\u0449\u0435\u0439 \u0433\u043b\u0430\u0437\u0443\u0440\u0438 \u0442\u044d\u0440\u0438\u044f\u043a\u0438 \u0441 \u0438\u043c\u0431\u0438\u0440\u0451\u043c \u0438 \u043c\u0451\u0434\u043e\u043c. \u041c\u044f\u0441\u043e \u0441\u043e\u0447\u043d\u043e\u0435, \u0433\u043b\u0430\u0437\u0443\u0440\u044c \u043b\u0438\u043f\u043a\u0430\u044f \u0438 \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u044c\u043d\u0430\u044f \u2014 \u043e\u0442\u043b\u0438\u0447\u043d\u0430\u044f \u0437\u0430\u043a\u0443\u0441\u043a\u0430 \u0438\u043b\u0438 \u043b\u0451\u0433\u043a\u043e\u0435 \u0433\u043e\u0440\u044f\u0447\u0435\u0435 \u0441 \u043d\u0430\u0441\u0442\u043e\u044f\u0449\u0438\u043c \u044f\u043f\u043e\u043d\u0441\u043a\u0438\u043c \u0432\u043a\u0443\u0441\u043e\u043c.","en":"Japanese chicken thigh skewers with green onion in a glossy teriyaki glaze with ginger and honey. Juicy meat, sticky caramelised glaze \u2014 a great appetiser or light main with a true Japanese flavour.","ua":"\u042f\u043f\u043e\u043d\u0441\u044c\u043a\u0456 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0437 \u043a\u0443\u0440\u044f\u0447\u043e\u0433\u043e \u0441\u0442\u0435\u0433\u043d\u0430 \u0456\u0437 \u0437\u0435\u043b\u0435\u043d\u043e\u044e \u0446\u0438\u0431\u0443\u043b\u0435\u044e \u0432 \u0431\u043b\u0438\u0441\u043a\u0443\u0447\u0456\u0439 \u0433\u043b\u0430\u0437\u0443\u0440\u0456 \u0442\u0435\u0440\u0456\u044f\u043a\u0456 \u0437 \u0456\u043c\u0431\u0438\u0440\u043e\u043c \u0456 \u043c\u0435\u0434\u043e\u043c. \u041c'\u044f\u0441\u043e \u0441\u043e\u043a\u043e\u0432\u0438\u0442\u0435, \u0433\u043b\u0430\u0437\u0443\u0440 \u043b\u0438\u043f\u043a\u0430 \u0439 \u043a\u0430\u0440\u0430\u043c\u0435\u043b\u044c\u043d\u0430 \u2014 \u0447\u0443\u0434\u043e\u0432\u0430 \u0437\u0430\u043a\u0443\u0441\u043a\u0430 \u0430\u0431\u043e \u043b\u0435\u0433\u043a\u0430 \u0433\u0430\u0440\u044f\u0447\u0430 \u0441\u0442\u0440\u0430\u0432\u0430 \u0437\u0456 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u0456\u043c \u044f\u043f\u043e\u043d\u0441\u044c\u043a\u0438\u043c \u0441\u043c\u0430\u043a\u043e\u043c."}$j$::jsonb, ingredients = $j${"ru":["\u041a\u0443\u0440\u0438\u043d\u043e\u0435 \u0431\u0435\u0434\u0440\u043e \u0431\u0435\u0437 \u043a\u043e\u0441\u0442\u0438 \u2014 700 \u0433","\u0417\u0435\u043b\u0451\u043d\u044b\u0439 \u043b\u0443\u043a \u2014 2\u20133 \u0441\u0442\u0435\u0431\u043b\u044f","\u0411\u0430\u043c\u0431\u0443\u043a\u043e\u0432\u044b\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u2014 10\u201312 \u0448\u0442","\u0421\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441 \u2014 100 \u043c\u043b","\u041c\u0438\u0440\u0438\u043d \u2014 50 \u043c\u043b","\u0421\u0430\u043a\u0435 \u2014 50 \u043c\u043b","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u044b\u0439 \u0441\u0430\u0445\u0430\u0440 \u2014 2 \u0441\u0442. \u043b.","\u041c\u0451\u0434 \u2014 1 \u0441\u0442. \u043b.","\u0422\u0451\u0440\u0442\u044b\u0439 \u0438\u043c\u0431\u0438\u0440\u044c \u2014 1 \u0447. \u043b.","\u0427\u0435\u0441\u043d\u043e\u043a \u2014 2 \u0437\u0443\u0431\u0447\u0438\u043a\u0430","\u041a\u0443\u043d\u0436\u0443\u0442 \u2014 1 \u0447. \u043b."],"en":["Boneless chicken thigh \u2014 700 g","Green onions \u2014 2\u20133 stalks","Bamboo skewers \u2014 10\u201312 pcs","Soy sauce \u2014 100 ml","Mirin \u2014 50 ml","Sake \u2014 50 ml","Brown sugar \u2014 2 tbsp","Honey \u2014 1 tbsp","Grated ginger \u2014 1 tsp","Garlic \u2014 2 cloves","Sesame seeds \u2014 1 tsp"],"ua":["\u041a\u0443\u0440\u044f\u0447\u0435 \u0441\u0442\u0435\u0433\u043d\u043e \u0431\u0435\u0437 \u043a\u0456\u0441\u0442\u043a\u0438 \u2014 700 \u0433","\u0417\u0435\u043b\u0435\u043d\u0430 \u0446\u0438\u0431\u0443\u043b\u044f \u2014 2\u20133 \u0441\u0442\u0435\u0431\u043b\u0430","\u0411\u0430\u043c\u0431\u0443\u043a\u043e\u0432\u0456 \u0448\u043f\u0430\u0436\u043a\u0438 \u2014 10\u201312 \u0448\u0442","\u0421\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441 \u2014 100 \u043c\u043b","\u041c\u0456\u0440\u0438\u043d \u2014 50 \u043c\u043b","\u0421\u0430\u043a\u0435 \u2014 50 \u043c\u043b","\u041a\u043e\u0440\u0438\u0447\u043d\u0435\u0432\u0438\u0439 \u0446\u0443\u043a\u043e\u0440 \u2014 2 \u0441\u0442. \u043b.","\u041c\u0435\u0434 \u2014 1 \u0441\u0442. \u043b.","\u0422\u0435\u0440\u0442\u0438\u0439 \u0456\u043c\u0431\u0438\u0440 \u2014 1 \u0447. \u043b.","\u0427\u0430\u0441\u043d\u0438\u043a \u2014 2 \u0437\u0443\u0431\u0447\u0438\u043a\u0438","\u041a\u0443\u043d\u0436\u0443\u0442 \u2014 1 \u0447. \u043b."]}$j$::jsonb, steps = $j${"ru":["\u0417\u0430\u043c\u043e\u0447\u0438\u0442\u0435 \u0431\u0430\u043c\u0431\u0443\u043a\u043e\u0432\u044b\u0435 \u0448\u043f\u0430\u0436\u043a\u0438 \u0432 \u0432\u043e\u0434\u0435 \u043d\u0430 30 \u043c\u0438\u043d\u0443\u0442.","\u041d\u0430\u0440\u0435\u0436\u044c\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443 \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u043c\u0438 \u043a\u0443\u0441\u043e\u0447\u043a\u0430\u043c\u0438 \u043d\u0430 \u043e\u0434\u0438\u043d \u0443\u043a\u0443\u0441, \u0431\u0435\u043b\u0443\u044e \u0447\u0430\u0441\u0442\u044c \u043b\u0443\u043a\u0430 \u2014 \u043e\u0442\u0440\u0435\u0437\u043a\u0430\u043c\u0438 \u043f\u043e 3 \u0441\u043c.","\u0414\u043b\u044f \u0441\u043e\u0443\u0441\u0430 \u0442\u044d\u0440\u0438\u044f\u043a\u0438 \u0441\u043e\u0435\u0434\u0438\u043d\u0438\u0442\u0435 \u0441\u043e\u0435\u0432\u044b\u0439 \u0441\u043e\u0443\u0441, \u043c\u0438\u0440\u0438\u043d, \u0441\u0430\u043a\u0435, \u0441\u0430\u0445\u0430\u0440, \u043c\u0451\u0434, \u0438\u043c\u0431\u0438\u0440\u044c \u0438 \u0447\u0435\u0441\u043d\u043e\u043a \u0438 \u0443\u0432\u0430\u0440\u0438\u0442\u0435 \u043d\u0430 \u0441\u043b\u0430\u0431\u043e\u043c \u043e\u0433\u043d\u0435 8\u201310 \u043c\u0438\u043d\u0443\u0442 \u0434\u043e \u0433\u0443\u0441\u0442\u043e\u0442\u044b.","\u041d\u0430\u043d\u0438\u0436\u0438\u0442\u0435 \u043a\u0443\u0440\u0438\u0446\u0443 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438, \u0447\u0435\u0440\u0435\u0434\u0443\u044f \u0441 \u043a\u0443\u0441\u043e\u0447\u043a\u0430\u043c\u0438 \u043b\u0443\u043a\u0430.","\u0416\u0430\u0440\u044c\u0442\u0435 \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c \u043e\u0433\u043d\u0435 10\u201312 \u043c\u0438\u043d\u0443\u0442, \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u043e \u043f\u0435\u0440\u0435\u0432\u043e\u0440\u0430\u0447\u0438\u0432\u0430\u044f.","\u0412\u043e \u0432\u0440\u0435\u043c\u044f \u0436\u0430\u0440\u043a\u0438 \u0449\u0435\u0434\u0440\u043e \u0441\u043c\u0430\u0437\u044b\u0432\u0430\u0439\u0442\u0435 \u0448\u0430\u0448\u043b\u044b\u0447\u043a\u0438 \u0441\u043e\u0443\u0441\u043e\u043c.","\u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0434\u0430\u0447\u0435\u0439 \u043f\u043e\u043a\u0440\u043e\u0439\u0442\u0435 \u0438\u0445 \u0441\u043e\u0443\u0441\u043e\u043c \u0435\u0449\u0451 \u0440\u0430\u0437.","\u041f\u043e\u0441\u044b\u043f\u044c\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0438 \u043d\u0430\u0440\u0435\u0437\u0430\u043d\u043d\u044b\u043c \u0437\u0435\u043b\u0451\u043d\u044b\u043c \u043b\u0443\u043a\u043e\u043c, \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0433\u043e\u0440\u044f\u0447\u0438\u043c\u0438 \u0441 \u0434\u043e\u043b\u044c\u043a\u0430\u043c\u0438 \u043b\u0438\u043c\u043e\u043d\u0430."],"en":["Soak the bamboo skewers in water for 30 minutes.","Cut the chicken into even bite-sized pieces and the white part of the green onions into 3 cm lengths.","For the teriyaki sauce, combine the soy sauce, mirin, sake, sugar, honey, ginger and garlic and simmer over low heat for 8\u201310 minutes until thickened.","Thread the chicken onto the skewers, alternating with the onion pieces.","Grill over high heat for 10\u201312 minutes, turning regularly.","Brush generously with the sauce while grilling.","Give them one final coat of glaze before serving.","Sprinkle with sesame seeds and sliced green onion and serve hot with lemon wedges."],"ua":["\u0417\u0430\u043c\u043e\u0447\u0456\u0442\u044c \u0431\u0430\u043c\u0431\u0443\u043a\u043e\u0432\u0456 \u0448\u043f\u0430\u0436\u043a\u0438 \u0443 \u0432\u043e\u0434\u0456 \u043d\u0430 30 \u0445\u0432\u0438\u043b\u0438\u043d.","\u041d\u0430\u0440\u0456\u0436\u0442\u0435 \u043a\u0443\u0440\u043a\u0443 \u043e\u0434\u043d\u0430\u043a\u043e\u0432\u0438\u043c\u0438 \u0448\u043c\u0430\u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u043d\u0430 \u043e\u0434\u0438\u043d \u0443\u043a\u0443\u0441, \u0431\u0456\u043b\u0443 \u0447\u0430\u0441\u0442\u0438\u043d\u0443 \u0446\u0438\u0431\u0443\u043b\u0456 \u2014 \u0432\u0456\u0434\u0440\u0456\u0437\u043a\u0430\u043c\u0438 \u043f\u043e 3 \u0441\u043c.","\u0414\u043b\u044f \u0441\u043e\u0443\u0441\u0443 \u0442\u0435\u0440\u0456\u044f\u043a\u0456 \u0437'\u0454\u0434\u043d\u0430\u0439\u0442\u0435 \u0441\u043e\u0454\u0432\u0438\u0439 \u0441\u043e\u0443\u0441, \u043c\u0456\u0440\u0438\u043d, \u0441\u0430\u043a\u0435, \u0446\u0443\u043a\u043e\u0440, \u043c\u0435\u0434, \u0456\u043c\u0431\u0438\u0440 \u0456 \u0447\u0430\u0441\u043d\u0438\u043a \u0442\u0430 \u0443\u0432\u0430\u0440\u0456\u0442\u044c \u043d\u0430 \u0441\u043b\u0430\u0431\u043a\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 8\u201310 \u0445\u0432\u0438\u043b\u0438\u043d \u0434\u043e \u0433\u0443\u0441\u0442\u043e\u0442\u0438.","\u041d\u0430\u043d\u0438\u0437\u0430\u0439\u0442\u0435 \u043a\u0443\u0440\u043a\u0443 \u043d\u0430 \u0448\u043f\u0430\u0436\u043a\u0438, \u0447\u0435\u0440\u0433\u0443\u044e\u0447\u0438 \u0437\u0456 \u0448\u043c\u0430\u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u0446\u0438\u0431\u0443\u043b\u0456.","\u0421\u043c\u0430\u0436\u0442\u0435 \u043d\u0430 \u0441\u0438\u043b\u044c\u043d\u043e\u043c\u0443 \u0432\u043e\u0433\u043d\u0456 10\u201312 \u0445\u0432\u0438\u043b\u0438\u043d, \u0440\u0435\u0433\u0443\u043b\u044f\u0440\u043d\u043e \u043f\u0435\u0440\u0435\u0432\u0435\u0440\u0442\u0430\u044e\u0447\u0438.","\u041f\u0456\u0434 \u0447\u0430\u0441 \u0441\u043c\u0430\u0436\u0435\u043d\u043d\u044f \u0449\u0435\u0434\u0440\u043e \u0437\u043c\u0430\u0449\u0443\u0439\u0442\u0435 \u0448\u0430\u0448\u043b\u0438\u0447\u043a\u0438 \u0441\u043e\u0443\u0441\u043e\u043c.","\u041f\u0435\u0440\u0435\u0434 \u043f\u043e\u0434\u0430\u0447\u0435\u044e \u0432\u043a\u0440\u0438\u0439\u0442\u0435 \u0457\u0445 \u0441\u043e\u0443\u0441\u043e\u043c \u0449\u0435 \u0440\u0430\u0437.","\u041f\u043e\u0441\u0438\u043f\u0442\u0435 \u043a\u0443\u043d\u0436\u0443\u0442\u043e\u043c \u0456 \u043d\u0430\u0440\u0456\u0437\u0430\u043d\u043e\u044e \u0437\u0435\u043b\u0435\u043d\u043e\u044e \u0446\u0438\u0431\u0443\u043b\u0435\u044e, \u043f\u043e\u0434\u0430\u0432\u0430\u0439\u0442\u0435 \u0433\u0430\u0440\u044f\u0447\u0438\u043c\u0438 \u0437 \u0447\u0430\u0441\u0442\u043e\u0447\u043a\u0430\u043c\u0438 \u043b\u0438\u043c\u043e\u043d\u0430."]}$j$::jsonb, tags = $j${"ru":["\u044f\u043f\u043e\u043d\u0441\u043a\u0430\u044f \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u0437\u0430\u043a\u0443\u0441\u043a\u0430","\u043a\u0443\u0440\u0438\u0446\u0430","\u0430\u0437\u0438\u0430\u0442\u0441\u043a\u0430\u044f \u043a\u0443\u0445\u043d\u044f"],"en":["japanese","grilled","appetizer","chicken","asian"],"ua":["\u044f\u043f\u043e\u043d\u0441\u044c\u043a\u0430 \u043a\u0443\u0445\u043d\u044f","\u0433\u0440\u0438\u043b\u044c","\u0437\u0430\u043a\u0443\u0441\u043a\u0430","\u043a\u0443\u0440\u043a\u0430","\u0430\u0437\u0456\u0439\u0441\u044c\u043a\u0430 \u043a\u0443\u0445\u043d\u044f"]}$j$::jsonb where slug = 'yakitori' and not (title ? 'ua');
